-- PicklePro: set up a NEW, EMPTY Supabase project in one go.
-- Paste the whole file into Supabase Dashboard -> SQL Editor -> New query -> Run.
--
-- It is every file in supabase/migrations, in order, so the project ends up the same as
-- one built with `supabase db push`. Use it ONLY on a new project: on an existing one,
-- use check_database.sql and the pickleproapp_upgrade_N.sql files instead.
-- If the SQL Editor says the query is too large, use `supabase link` + `supabase db push`.
-- Afterwards run check_database.sql: every row should say OK.
-- Generated by make_new_project_setup.sh; do not edit by hand.


-- ════════════════ 20260924000100_sessions_and_video_assets.sql ════════════════

-- Sessions and private video assets.
--
-- Access model: every row belongs to exactly one auth user (owner_id). Players
-- can only see and change their own rows. Sharing with a buddy/coach is NOT
-- implemented here; it needs an explicit grant table and an adviser decision
-- (see docs/ADVISER_DECISIONS.md).

-- ── sessions ────────────────────────────────────────────────────────────────
create table public.sessions (
  id                uuid primary key default gen_random_uuid(),
  owner_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  title             text not null check (char_length(btrim(title)) between 1 and 120),
  session_date      date not null default current_date,
  -- Gameplay context (paper §3.2.1 / §3.2.6).
  session_context   text not null check (session_context in ('practice', 'casual_match', 'tournament', 'leveling_game')),
  play_format       text not null check (play_format in ('singles', 'doubles', 'wall_practice', 'ball_machine', 'drill_other')),
  performance_scope text not null default 'individual' check (performance_scope in ('individual', 'pair')),
  notes             text check (char_length(notes) <= 2000),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index sessions_owner_date_idx on public.sessions (owner_id, session_date desc, created_at desc);

create function public.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

create trigger sessions_touch_updated_at before update on public.sessions
  for each row execute function public.touch_updated_at();

alter table public.sessions enable row level security;

create policy sessions_select_own on public.sessions for select to authenticated
  using (owner_id = (select auth.uid()));
create policy sessions_insert_own on public.sessions for insert to authenticated
  with check (owner_id = (select auth.uid()));
create policy sessions_update_own on public.sessions for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy sessions_delete_own on public.sessions for delete to authenticated
  using (owner_id = (select auth.uid()));

-- ── video_assets ────────────────────────────────────────────────────────────
-- Storage path convention: <owner_id>/<session_id>/<video_id>.<ext>
-- One video per session for this milestone.
create table public.video_assets (
  id                uuid primary key default gen_random_uuid(),
  owner_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  session_id        uuid not null unique references public.sessions (id) on delete cascade,
  storage_bucket    text not null default 'session-videos' check (storage_bucket = 'session-videos'),
  storage_path      text not null unique,
  original_filename text not null check (char_length(original_filename) between 1 and 255),
  mime_type         text not null check (mime_type in ('video/mp4', 'video/quicktime', 'video/webm', 'video/x-msvideo')),
  -- 500 MiB, matching the bucket limit below. The hosted project's global
  -- upload limit may be lower (50 MB on the Free plan).
  byte_size         bigint not null check (byte_size > 0 and byte_size <= 524288000),
  upload_status     text not null default 'pending' check (upload_status in ('pending', 'uploaded')),
  created_at        timestamptz not null default now(),
  uploaded_at       timestamptz,
  constraint video_assets_path_convention check (
    split_part(storage_path, '/', 1) = owner_id::text
    and split_part(storage_path, '/', 2) = session_id::text
    and split_part(storage_path, '/', 3) like id::text || '.%'
    and split_part(storage_path, '/', 4) = ''
  )
);

create index video_assets_owner_idx on public.video_assets (owner_id);

alter table public.video_assets enable row level security;

create policy video_assets_select_own on public.video_assets for select to authenticated
  using (owner_id = (select auth.uid()));
-- A player registers an upload for one of their own sessions. upload_status
-- can only move to 'uploaded' through finalize_video_upload(), which checks
-- that the object really exists in storage.
create policy video_assets_insert_own on public.video_assets for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    and upload_status = 'pending'
    and exists (select 1 from public.sessions s where s.id = session_id and s.owner_id = (select auth.uid()))
  );
create policy video_assets_delete_own on public.video_assets for delete to authenticated
  using (owner_id = (select auth.uid()));

-- ── Table privileges (defence in depth on top of RLS) ───────────────────────
revoke all on public.sessions, public.video_assets from anon;
revoke all on public.sessions, public.video_assets from authenticated;
grant select, insert, update, delete on public.sessions to authenticated;
grant select, insert, delete on public.video_assets to authenticated;
grant all on public.sessions, public.video_assets to service_role;
revoke all on function public.touch_updated_at() from public, anon, authenticated;

-- ── Private storage bucket ──────────────────────────────────────────────────
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('session-videos', 'session-videos', false, 524288000,
        array['video/mp4', 'video/quicktime', 'video/webm', 'video/x-msvideo'])
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Uploads are only accepted into the caller's own folder AND for a registered,
-- still-pending video asset at exactly that path.
create policy session_videos_insert_own on storage.objects for insert to authenticated
  with check (
    bucket_id = 'session-videos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and exists (
      select 1 from public.video_assets v
      where v.storage_path = name and v.owner_id = (select auth.uid()) and v.upload_status = 'pending'
    )
  );
create policy session_videos_select_own on storage.objects for select to authenticated
  using (bucket_id = 'session-videos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy session_videos_delete_own on storage.objects for delete to authenticated
  using (bucket_id = 'session-videos' and (storage.foldername(name))[1] = (select auth.uid())::text);


-- ════════════════ 20260924000200_analysis_jobs_and_results.sql ════════════════

-- Analysis jobs (exactly one per uploaded video) and their results.
--
-- Players can read their jobs/results but cannot write them directly. They act
-- through two SECURITY DEFINER functions:
--   finalize_video_upload(video_id, params) → marks the upload complete, creates the job once
--   request_reanalysis(job_id, params)    → re-queues a finished/failed job
-- The worker uses the service role and four functions that implement a lease:
--   claim_analysis_job / heartbeat_analysis_job / complete_analysis_job / fail_analysis_job

create table public.analysis_jobs (
  id               uuid primary key default gen_random_uuid(),
  owner_id         uuid not null references auth.users (id) on delete cascade,
  video_asset_id   uuid not null unique references public.video_assets (id) on delete cascade,
  session_id       uuid not null references public.sessions (id) on delete cascade,
  status           text not null default 'queued' check (status in ('queued', 'processing', 'completed', 'failed')),
  -- Optional analysis inputs: {"calibration": {...}, "selection": {...}, "experimental_zones": bool}
  params           jsonb not null default '{}'::jsonb check (jsonb_typeof(params) = 'object'),
  attempts         int not null default 0 check (attempts >= 0),
  max_attempts     int not null default 3 check (max_attempts between 1 and 10),
  available_at     timestamptz not null default now(),
  locked_by        text,
  lease_expires_at timestamptz,
  error_code       text,
  error_message    text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  started_at       timestamptz,
  finished_at      timestamptz
);

create index analysis_jobs_claimable_idx on public.analysis_jobs (available_at, created_at)
  where status in ('queued', 'processing');
create index analysis_jobs_owner_idx on public.analysis_jobs (owner_id);

create table public.analysis_results (
  id                  uuid primary key default gen_random_uuid(),
  job_id              uuid not null unique references public.analysis_jobs (id) on delete cascade,
  owner_id            uuid not null references auth.users (id) on delete cascade,
  session_id          uuid not null references public.sessions (id) on delete cascade,
  video_asset_id      uuid not null references public.video_assets (id) on delete cascade,
  schema_version      text not null,
  result_status       text not null check (result_status in ('ok', 'insufficient_data')),
  data_origin         text not null check (data_origin in ('measured', 'test_fixture')),
  pipeline_version    text not null,
  analyzed_duration_s double precision,
  video_duration_s    double precision,
  fraction_analyzed   double precision,
  result              jsonb not null,
  created_at          timestamptz not null default now()
);

create index analysis_results_owner_idx on public.analysis_results (owner_id, created_at desc);

alter table public.analysis_jobs enable row level security;
alter table public.analysis_results enable row level security;

create policy analysis_jobs_select_own on public.analysis_jobs for select to authenticated
  using (owner_id = (select auth.uid()));
create policy analysis_results_select_own on public.analysis_results for select to authenticated
  using (owner_id = (select auth.uid()));

revoke all on public.analysis_jobs, public.analysis_results from anon, authenticated;
grant select on public.analysis_jobs, public.analysis_results to authenticated;
grant all on public.analysis_jobs, public.analysis_results to service_role;

-- ── Player-facing functions ────────────────────────────────────────────────

-- Idempotent: calling it twice (double click, retry after a network error, two
-- tabs) returns the same job. The row lock on the video serializes concurrent
-- calls and the unique index on analysis_jobs.video_asset_id backs it up.
-- p_params is only used when the job is first created; later calls return the
-- existing job unchanged (use request_reanalysis to change params).
create function public.finalize_video_upload(p_video_id uuid, p_params jsonb default '{}'::jsonb)
returns public.analysis_jobs
language plpgsql security definer set search_path = '' as $$
declare
  v public.video_assets;
  j public.analysis_jobs;
  obj_size bigint;
begin
  if p_params is null or jsonb_typeof(p_params) <> 'object' then
    raise exception 'invalid_params' using errcode = '22023';
  end if;
  select * into v from public.video_assets
   where id = p_video_id and owner_id = auth.uid()
   for update;
  if not found then
    raise exception 'video_not_found' using errcode = 'P0002';
  end if;

  if v.upload_status = 'pending' then
    select (o.metadata ->> 'size')::bigint into obj_size
      from storage.objects o
     where o.bucket_id = v.storage_bucket and o.name = v.storage_path;
    if not found then
      raise exception 'upload_incomplete' using errcode = 'P0001',
        hint = 'The file has not finished uploading to storage.';
    end if;
    update public.video_assets
       set upload_status = 'uploaded', uploaded_at = now(), byte_size = coalesce(obj_size, byte_size)
     where id = v.id;
  end if;

  insert into public.analysis_jobs (owner_id, video_asset_id, session_id, params)
  values (v.owner_id, v.id, v.session_id, p_params)
  on conflict (video_asset_id) do nothing;

  select * into j from public.analysis_jobs where video_asset_id = v.id;
  return j;
end $$;

-- Re-run analysis (e.g. after adding calibration). Keep the last published
-- result until the replacement is complete, so a failed retry cannot erase it.
create function public.request_reanalysis(p_job_id uuid, p_params jsonb default null)
returns public.analysis_jobs
language plpgsql security definer set search_path = '' as $$
declare
  j public.analysis_jobs;
begin
  if p_params is not null and jsonb_typeof(p_params) <> 'object' then
    raise exception 'invalid_params' using errcode = '22023';
  end if;
  select * into j from public.analysis_jobs
   where id = p_job_id and owner_id = auth.uid()
   for update;
  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;
  if j.status not in ('completed', 'failed') then
    raise exception 'job_not_finished' using errcode = 'P0001', hint = 'Wait for the current run to finish.';
  end if;
  update public.analysis_jobs
     set status = 'queued', attempts = 0, available_at = now(), params = coalesce(p_params, params),
         error_code = null, error_message = null, locked_by = null, lease_expires_at = null,
         started_at = null, finished_at = null, updated_at = now()
   where id = j.id
  returning * into j;
  return j;
end $$;

-- ── Worker functions (service role only) ───────────────────────────────────

create function public.claim_analysis_job(p_worker_id text, p_lease_seconds int default 300)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  j public.analysis_jobs;
  v public.video_assets;
begin
  -- A job whose final attempt's worker disappeared cannot be retried again.
  update public.analysis_jobs
     set status = 'failed', locked_by = null, lease_expires_at = null, finished_at = now(), updated_at = now(),
         error_code = 'lease_expired', error_message = 'The worker stopped responding on the final attempt.'
   where status = 'processing' and lease_expires_at < now() and attempts >= max_attempts;

  select * into j from public.analysis_jobs
   where (status = 'queued' and available_at <= now())
      or (status = 'processing' and lease_expires_at < now())
   order by available_at, created_at
   for update skip locked
   limit 1;
  if not found then
    return null;
  end if;

  update public.analysis_jobs
     set status = 'processing', locked_by = p_worker_id, attempts = attempts + 1,
         lease_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)),
         started_at = coalesce(started_at, now()), updated_at = now()
   where id = j.id
  returning * into j;

  select * into v from public.video_assets where id = j.video_asset_id;
  return jsonb_build_object(
    'id', j.id, 'owner_id', j.owner_id, 'video_asset_id', j.video_asset_id, 'session_id', j.session_id,
    'storage_bucket', v.storage_bucket, 'storage_path', v.storage_path, 'original_filename', v.original_filename,
    'attempts', j.attempts, 'max_attempts', j.max_attempts, 'params', j.params);
end $$;

create function public.heartbeat_analysis_job(p_job_id uuid, p_worker_id text, p_lease_seconds int default 300)
returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  update public.analysis_jobs
     set lease_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)), updated_at = now()
   where id = p_job_id and status = 'processing' and locked_by = p_worker_id and lease_expires_at >= now();
  return found;
end $$;

-- Raises 'lease_lost' unless the caller still holds a live lease on the job.
create function public._lock_held_job(p_job_id uuid, p_worker_id text)
returns public.analysis_jobs
language plpgsql security definer set search_path = '' as $$
declare
  j public.analysis_jobs;
begin
  select * into j from public.analysis_jobs where id = p_job_id for update;
  if not found or j.status <> 'processing' or j.locked_by is distinct from p_worker_id
     or j.lease_expires_at < now() then
    raise exception 'lease_lost' using errcode = 'P0001';
  end if;
  return j;
end $$;

create function public.complete_analysis_job(p_job_id uuid, p_worker_id text, p_result jsonb)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  j public.analysis_jobs;
begin
  j := public._lock_held_job(p_job_id, p_worker_id);
  if p_result ->> 'schema_version' is null
     or coalesce(p_result ->> 'status', '') not in ('ok', 'insufficient_data')
     or coalesce(p_result ->> 'data_origin', '') not in ('measured', 'test_fixture')
     or p_result #>> '{provenance,pipeline_version}' is null then
    raise exception 'invalid_result' using errcode = '22023';
  end if;

  insert into public.analysis_results (
    job_id, owner_id, session_id, video_asset_id, schema_version, result_status, data_origin,
    pipeline_version, analyzed_duration_s, video_duration_s, fraction_analyzed, result)
  values (
    j.id, j.owner_id, j.session_id, j.video_asset_id, p_result ->> 'schema_version', p_result ->> 'status',
    p_result ->> 'data_origin', p_result #>> '{provenance,pipeline_version}',
    (p_result #>> '{coverage,analyzed_duration_s}')::double precision,
    (p_result #>> '{video,container_duration_s}')::double precision,
    (p_result #>> '{coverage,fraction_of_video_analyzed}')::double precision,
    p_result)
  on conflict (job_id) do update set
    schema_version = excluded.schema_version, result_status = excluded.result_status,
    data_origin = excluded.data_origin, pipeline_version = excluded.pipeline_version,
    analyzed_duration_s = excluded.analyzed_duration_s, video_duration_s = excluded.video_duration_s,
    fraction_analyzed = excluded.fraction_analyzed, result = excluded.result, created_at = now();

  update public.analysis_jobs
     set status = 'completed', locked_by = null, lease_expires_at = null, error_code = null,
         error_message = null, finished_at = now(), updated_at = now()
   where id = j.id;
end $$;

-- Retryable failures go back to the queue with exponential backoff (30s, 60s, ...).
create function public.fail_analysis_job(p_job_id uuid, p_worker_id text, p_error_code text,
                                         p_error_message text, p_retryable boolean)
returns text
language plpgsql security definer set search_path = '' as $$
declare
  j public.analysis_jobs;
  new_status text;
begin
  j := public._lock_held_job(p_job_id, p_worker_id);
  new_status := case when p_retryable and j.attempts < j.max_attempts then 'queued' else 'failed' end;
  update public.analysis_jobs
     set status = new_status, locked_by = null, lease_expires_at = null,
         error_code = left(p_error_code, 64), error_message = left(p_error_message, 2000),
         available_at = case when new_status = 'queued'
                             then now() + make_interval(secs => 30 * power(2, greatest(j.attempts - 1, 0)))
                             else available_at end,
         finished_at = case when new_status = 'failed' then now() else null end,
         updated_at = now()
   where id = j.id;
  return new_status;
end $$;

-- Supabase grants EXECUTE on new public functions to anon/authenticated by
-- default, so every function is locked down explicitly.
revoke all on function public.finalize_video_upload(uuid, jsonb) from public, anon, authenticated;
revoke all on function public.request_reanalysis(uuid, jsonb) from public, anon, authenticated;
revoke all on function public.claim_analysis_job(text, int) from public, anon, authenticated;
revoke all on function public.heartbeat_analysis_job(uuid, text, int) from public, anon, authenticated;
revoke all on function public._lock_held_job(uuid, text) from public, anon, authenticated;
revoke all on function public.complete_analysis_job(uuid, text, jsonb) from public, anon, authenticated;
revoke all on function public.fail_analysis_job(uuid, text, text, text, boolean) from public, anon, authenticated;

grant execute on function public.finalize_video_upload(uuid, jsonb) to authenticated;
grant execute on function public.request_reanalysis(uuid, jsonb) to authenticated;
grant execute on function public.claim_analysis_job(text, int) to service_role;
grant execute on function public.heartbeat_analysis_job(uuid, text, int) to service_role;
grant execute on function public.complete_analysis_job(uuid, text, jsonb) to service_role;
grant execute on function public.fail_analysis_job(uuid, text, text, text, boolean) to service_role;


-- ════════════════ 20260928000100_dev_mock_data.sql ════════════════

-- Developer mock data for the "Dev mode" button on the sign-in screen.
--
-- The button signs in as a Supabase *anonymous* user and calls
-- seed_dev_mock_data() with generated sessions and results. Players cannot
-- normally write results (only the worker can), so this SECURITY DEFINER
-- function does it, with strict limits:
--
--   * only anonymous users may call it, so real accounts never get mock rows;
--   * it only writes rows owned by the caller, which RLS keeps private;
--   * every result must carry provenance.pipeline_version = 'dev-mock', which
--     the app shows as a DEV MOCK DATA warning;
--   * it replaces the caller's previous mock sessions instead of piling up.
--
-- Requires "Allow anonymous sign-ins" (Authentication → Sign In / Providers).
-- Anonymous users get the `authenticated` role, like any signed-in user.

create or replace function public.seed_dev_mock_data(p_sessions jsonb)
returns int
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  s jsonb;
  r jsonb;
  v_session uuid;
  v_video uuid;
  v_job uuid;
  n int := 0;
begin
  if uid is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) is not true then
    raise exception 'dev_mock_requires_anonymous_user' using errcode = '42501',
      hint = 'Mock data can only be created for a Dev mode (anonymous) sign-in.';
  end if;
  if p_sessions is null or jsonb_typeof(p_sessions) <> 'array'
     or jsonb_array_length(p_sessions) not between 1 and 10 then
    raise exception 'invalid_mock_sessions' using errcode = '22023';
  end if;

  -- Replace, not accumulate. Cascades remove videos, jobs and results.
  delete from public.sessions where owner_id = uid and title like '[Dev mock]%';

  for s in select * from jsonb_array_elements(p_sessions) loop
    r := s -> 'result';
    if r ->> 'schema_version' is null
       or coalesce(r ->> 'status', '') not in ('ok', 'insufficient_data')
       or coalesce(r ->> 'data_origin', '') not in ('measured', 'test_fixture')
       or r #>> '{provenance,pipeline_version}' is distinct from 'dev-mock' then
      raise exception 'invalid_mock_result' using errcode = '22023',
        hint = 'Mock results must be valid v1 results with provenance.pipeline_version = dev-mock.';
    end if;

    insert into public.sessions (owner_id, title, session_date, session_context, play_format, notes)
    values (uid, '[Dev mock] ' || left(coalesce(s ->> 'title', 'Session'), 100),
            coalesce((s ->> 'session_date')::date, current_date),
            coalesce(s ->> 'session_context', 'practice'), coalesce(s ->> 'play_format', 'singles'),
            'Generated by Dev mode. Not an analysis of a real video.')
    returning id into v_session;

    v_video := gen_random_uuid();
    insert into public.video_assets (id, owner_id, session_id, storage_path, original_filename, mime_type,
                                     byte_size, upload_status, uploaded_at)
    values (v_video, uid, v_session, uid || '/' || v_session || '/' || v_video || '.mp4',
            'dev_mock_' || (n + 1) || '.mp4', 'video/mp4', 1, 'uploaded', now());

    insert into public.analysis_jobs (owner_id, video_asset_id, session_id, status, attempts, started_at, finished_at)
    values (uid, v_video, v_session, 'completed', 1, now(), now())
    returning id into v_job;

    insert into public.analysis_results (
      job_id, owner_id, session_id, video_asset_id, schema_version, result_status, data_origin,
      pipeline_version, analyzed_duration_s, video_duration_s, fraction_analyzed, result)
    values (
      v_job, uid, v_session, v_video, r ->> 'schema_version', r ->> 'status', r ->> 'data_origin', 'dev-mock',
      (r #>> '{coverage,analyzed_duration_s}')::double precision,
      (r #>> '{video,container_duration_s}')::double precision,
      (r #>> '{coverage,fraction_of_video_analyzed}')::double precision,
      r);
    n := n + 1;
  end loop;
  return n;
end $$;

revoke all on function public.seed_dev_mock_data(jsonb) from public, anon, authenticated;
grant execute on function public.seed_dev_mock_data(jsonb) to authenticated;


-- ════════════════ 20260928000200_session_goals.sql ════════════════

-- Keep a player's own assessment separate from measured video results.
-- Existing sessions have no selected goals or self ratings.
alter table public.sessions
  add column improvement_goals text[] not null default '{}'::text[],
  add column positioning_rating smallint,
  add column shot_outcomes_rating smallint,
  add column shot_technique_rating smallint;

alter table public.sessions
  add constraint sessions_improvement_goals_check
    check (improvement_goals <@ array['positioning', 'shot_outcomes', 'shot_technique']::text[]),
  add constraint sessions_positioning_rating_check check (positioning_rating between 1 and 5),
  add constraint sessions_shot_outcomes_rating_check check (shot_outcomes_rating between 1 and 5),
  add constraint sessions_shot_technique_rating_check check (shot_technique_rating between 1 and 5);


-- ════════════════ 20260929000100_capture_and_consent.sql ════════════════

-- Private participant capture and an uploader attestation before video upload.
-- Sharing these records is deliberately not granted by report access.
alter table public.sessions drop constraint sessions_session_context_check;
alter table public.sessions add constraint sessions_session_context_check
  check (session_context in ('practice', 'casual_match', 'tournament', 'leveling_game', 'drill'));

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null check (char_length(btrim(display_name)) between 1 and 80),
  dominant_hand text check (dominant_hand in ('right', 'left', 'ambidextrous')),
  years_playing numeric(4,1) check (years_playing between 0 and 99),
  usual_format text check (usual_format in ('singles', 'doubles', 'both')),
  self_level text check (char_length(btrim(self_level)) between 1 and 40),
  is_adult_confirmed boolean not null default false,
  updated_at timestamptz not null default now()
);
create trigger profiles_touch_updated_at before update on public.profiles
  for each row execute function public.touch_updated_at();
alter table public.profiles enable row level security;
create policy profiles_self on public.profiles for all to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
revoke all on public.profiles from anon, authenticated;
grant select, insert, update, delete on public.profiles to authenticated;
grant all on public.profiles to service_role;

-- Logging-only formats cannot acquire a video or enter the CV queue through
-- direct API calls, even if a client bypasses the upload screen.
create function public.require_court_video_format() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from public.sessions s where s.id = new.session_id
    and s.play_format in ('wall_practice', 'ball_machine')) then
    raise exception 'logging_only_format' using errcode = '22023';
  end if;
  return new;
end $$;
create trigger video_asset_court_format before insert or update of session_id on public.video_assets
  for each row execute function public.require_court_video_format();
create trigger analysis_job_court_format before insert or update of status on public.analysis_jobs
  for each row execute function public.require_court_video_format();
revoke all on function public.require_court_video_format() from public, anon, authenticated;

alter table public.sessions
  add column actual_start_at timestamptz,
  add column actual_end_at timestamptz,
  add constraint sessions_actual_times_check
    check (actual_end_at is null or actual_start_at is null or actual_end_at > actual_start_at);

create table public.session_participants (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions(id) on delete cascade,
  player_id uuid references auth.users(id) on delete set null,
  role text not null check (role in ('uploader', 'partner', 'opponent')),
  link_status text not null default 'anonymous' check (link_status in ('anonymous', 'accepted')),
  created_at timestamptz not null default now(),
  unique (session_id, player_id),
  check ((player_id is null and link_status = 'anonymous') or player_id is not null)
);

create function public.add_uploader_participant() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.session_participants(session_id, player_id, role, link_status)
  values (new.id, new.owner_id, 'uploader', 'accepted');
  return new;
end $$;
create trigger session_uploader_participant after insert on public.sessions
  for each row execute function public.add_uploader_participant();
insert into public.session_participants(session_id, player_id, role, link_status)
select s.id, s.owner_id, 'uploader', 'accepted' from public.sessions s
where not exists (select 1 from public.session_participants p where p.session_id = s.id and p.player_id = s.owner_id);

create table public.checkins (
  participant_id uuid primary key references public.session_participants(id) on delete cascade,
  captured_at timestamptz not null default now(),
  warmup_done boolean,
  sleep_hours numeric(4,1) check (sleep_hours between 0 and 24),
  readiness smallint check (readiness between 1 and 5),
  focus text check (char_length(focus) <= 500),
  timing_status text not null default 'unverified' check (timing_status in ('pre_game', 'retrospective', 'unverified'))
);
create function public.set_checkin_timing() returns trigger
language plpgsql security definer set search_path = '' as $$
declare start_time timestamptz;
begin
  if tg_op = 'INSERT' then
    new.captured_at := now();
  elsif row(new.warmup_done, new.sleep_hours, new.readiness, new.focus)
      is distinct from row(old.warmup_done, old.sleep_hours, old.readiness, old.focus) then
    -- A changed answer is a new capture. A reclassification caused only by
    -- correcting actual_start_at must retain the original capture time.
    new.captured_at := now();
  else
    new.captured_at := old.captured_at;
  end if;
  select s.actual_start_at into start_time from public.session_participants p
  join public.sessions s on s.id = p.session_id where p.id = new.participant_id;
  new.timing_status := case when start_time is null then 'unverified'
    when new.captured_at < start_time then 'pre_game' else 'retrospective' end;
  return new;
end $$;
create trigger checkin_timing before insert or update on public.checkins
  for each row execute function public.set_checkin_timing();
create function public.refresh_checkin_timing() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.actual_start_at is distinct from old.actual_start_at then
    update public.checkins c set timing_status = case
      when new.actual_start_at is null then 'unverified'
      when c.captured_at < new.actual_start_at then 'pre_game'
      else 'retrospective' end
    from public.session_participants p
    where p.id = c.participant_id and p.session_id = new.id;
  end if;
  return new;
end $$;
create trigger session_start_retimes_checkins after update of actual_start_at on public.sessions
  for each row execute function public.refresh_checkin_timing();

create table public.recovery_logs (
  participant_id uuid primary key references public.session_participants(id) on delete cascade,
  captured_at timestamptz not null default now(),
  exertion smallint check (exertion between 1 and 10),
  soreness smallint check (soreness between 1 and 5),
  cooldown_done boolean
);
create table public.reflections (
  participant_id uuid primary key references public.session_participants(id) on delete cascade,
  captured_at timestamptz not null default now(),
  went_well text check (char_length(went_well) <= 2000),
  change_next text check (char_length(change_next) <= 2000)
);
create function public.stamp_capture_time() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'INSERT' then new.captured_at := now();
  else new.captured_at := old.captured_at; end if;
  return new;
end $$;
create trigger recovery_capture_time before insert or update on public.recovery_logs
  for each row execute function public.stamp_capture_time();
create trigger reflection_capture_time before insert or update on public.reflections
  for each row execute function public.stamp_capture_time();

create table public.consent_records (
  id uuid primary key default gen_random_uuid(),
  player_id uuid not null references auth.users(id) on delete cascade,
  policy_version text not null,
  accepted_at timestamptz not null default now(),
  scope text not null check (scope = 'recording_upload'),
  retention_days integer not null check (retention_days = 30)
);
create function public.stamp_consent_time() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.accepted_at := now();
  return new;
end $$;
create trigger consent_time before insert on public.consent_records
  for each row execute function public.stamp_consent_time();

alter table public.session_participants enable row level security;
alter table public.checkins enable row level security;
alter table public.recovery_logs enable row level security;
alter table public.reflections enable row level security;
alter table public.consent_records enable row level security;
create policy participants_self on public.session_participants for select to authenticated
  using (player_id = (select auth.uid()));
create policy checkins_self on public.checkins for all to authenticated
  using (exists (select 1 from public.session_participants p where p.id = participant_id and p.player_id = (select auth.uid())))
  with check (exists (select 1 from public.session_participants p where p.id = participant_id and p.player_id = (select auth.uid())));
create policy recovery_self on public.recovery_logs for all to authenticated
  using (exists (select 1 from public.session_participants p where p.id = participant_id and p.player_id = (select auth.uid())))
  with check (exists (select 1 from public.session_participants p where p.id = participant_id and p.player_id = (select auth.uid())));
create policy reflections_self on public.reflections for all to authenticated
  using (exists (select 1 from public.session_participants p where p.id = participant_id and p.player_id = (select auth.uid())))
  with check (exists (select 1 from public.session_participants p where p.id = participant_id and p.player_id = (select auth.uid())));
create policy consent_self on public.consent_records for select to authenticated
  using (player_id = (select auth.uid()));
create policy consent_insert_self on public.consent_records for insert to authenticated
  with check (player_id = (select auth.uid()) and policy_version = '2026-09-29-v4');

revoke all on public.session_participants, public.checkins, public.recovery_logs,
  public.reflections, public.consent_records from anon, authenticated;
grant select on public.session_participants to authenticated;
grant select, insert, update, delete on public.checkins, public.recovery_logs, public.reflections to authenticated;
grant select, insert on public.consent_records to authenticated;
grant all on public.session_participants, public.checkins, public.recovery_logs,
  public.reflections, public.consent_records to service_role;
revoke all on function public.add_uploader_participant() from public, anon, authenticated;
revoke all on function public.set_checkin_timing() from public, anon, authenticated;
revoke all on function public.refresh_checkin_timing() from public, anon, authenticated;
revoke all on function public.stamp_consent_time() from public, anon, authenticated;
revoke all on function public.stamp_capture_time() from public, anon, authenticated;

-- A browser cannot bypass the consent screen by uploading straight to Storage.
drop policy session_videos_insert_own on storage.objects;
create policy session_videos_insert_own on storage.objects for insert to authenticated
  with check (
    bucket_id = 'session-videos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and exists (select 1 from public.video_assets v
      where v.storage_path = name and v.owner_id = (select auth.uid()) and v.upload_status = 'pending')
    and exists (select 1 from public.consent_records c
      where c.player_id = (select auth.uid()) and c.policy_version = '2026-09-29-v4')
  );

-- Preserve the last published report while reanalysis is queued or fails.
create or replace function public.request_reanalysis(p_job_id uuid, p_params jsonb default null)
returns public.analysis_jobs
language plpgsql security definer set search_path = '' as $$
declare j public.analysis_jobs;
begin
  if p_params is not null and jsonb_typeof(p_params) <> 'object' then
    raise exception 'invalid_params' using errcode = '22023';
  end if;
  select * into j from public.analysis_jobs
    where id = p_job_id and owner_id = auth.uid() for update;
  if not found then
    raise exception 'job_not_found' using errcode = 'P0002';
  end if;
  if j.status not in ('completed', 'failed') then
    raise exception 'job_not_finished' using errcode = 'P0001', hint = 'Wait for the current run to finish.';
  end if;
  update public.analysis_jobs
    set status = 'queued', attempts = 0, available_at = now(), params = coalesce(p_params, params),
        error_code = null, error_message = null, locked_by = null, lease_expires_at = null,
        started_at = null, finished_at = null, updated_at = now()
    where id = j.id returning * into j;
  return j;
end $$;


-- ════════════════ 20260929000200_versioned_analysis_runs.sql ════════════════

-- Versioned analysis beside the existing job/result API. A reanalysis creates a
-- new run; the session switches to it only after successful publication.
create table public.analysis_runs (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  session_id uuid not null references public.sessions(id) on delete cascade,
  video_asset_id uuid not null references public.video_assets(id) on delete cascade,
  job_id uuid not null references public.analysis_jobs(id) on delete cascade,
  run_number integer not null check (run_number > 0),
  status text not null check (status in ('queued', 'processing', 'completed', 'failed')),
  params jsonb not null default '{}'::jsonb check (jsonb_typeof(params) = 'object'),
  metric_definition_version text not null default 'v4-draft-2026-09-29',
  pipeline_version text,
  source_sha256 text,
  code_revision text,
  model_versions jsonb not null default '{}'::jsonb check (jsonb_typeof(model_versions) = 'object'),
  result_schema_version text,
  result_status text check (result_status in ('ok', 'insufficient_data')),
  result jsonb,
  error_code text,
  error_message text,
  created_at timestamptz not null default now(),
  started_at timestamptz,
  completed_at timestamptz,
  published_at timestamptz,
  unique (session_id, run_number),
  check ((status = 'completed') = (result is not null))
);
create index analysis_runs_owner_session_idx on public.analysis_runs(owner_id, session_id, run_number desc);
alter table public.analysis_runs enable row level security;
create policy analysis_runs_select_own on public.analysis_runs for select to authenticated
  using (owner_id = (select auth.uid()));
revoke all on public.analysis_runs from anon, authenticated;
grant select on public.analysis_runs to authenticated;
grant all on public.analysis_runs to service_role;

alter table public.sessions add column active_run_id uuid references public.analysis_runs(id) on delete set null;
alter table public.analysis_jobs add column current_run_id uuid references public.analysis_runs(id) on delete set null;
alter table public.analysis_results add column run_id uuid references public.analysis_runs(id) on delete set null;

-- The session owner may edit ordinary session details, but publication is a
-- worker operation. Also reject pointers to a run from a different session.
create function public.guard_active_run() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.active_run_id is distinct from old.active_run_id then
    if current_user = 'authenticated' then
      raise exception 'active_run_is_worker_managed' using errcode = '42501';
    end if;
    if new.active_run_id is not null and not exists
      (select 1 from public.analysis_runs r where r.id = new.active_run_id
        and r.session_id = new.id and r.status = 'completed') then
      raise exception 'invalid_active_run' using errcode = '22023';
    end if;
  end if;
  return new;
end $$;
create trigger sessions_guard_active_run before update on public.sessions
  for each row execute function public.guard_active_run();
revoke all on function public.guard_active_run() from public, anon, authenticated;

-- Existing published reports become run 1. A queued or failed reanalysis that
-- was already in flight gets a separate run; the published report stays active.
insert into public.analysis_runs(owner_id, session_id, video_asset_id, job_id, run_number, status,
  params, pipeline_version, source_sha256, result_schema_version, result_status, result,
  created_at, completed_at, published_at)
select r.owner_id, r.session_id, r.video_asset_id, r.job_id, 1, 'completed', j.params,
  r.pipeline_version, r.result #>> '{provenance,source,sha256}', r.schema_version, r.result_status,
  r.result, r.created_at, coalesce(j.finished_at, r.created_at), r.created_at
from public.analysis_results r join public.analysis_jobs j on j.id = r.job_id;
update public.analysis_results r set run_id = ar.id
from public.analysis_runs ar where ar.job_id = r.job_id and ar.run_number = 1;
update public.sessions s set active_run_id = ar.id
from public.analysis_runs ar where ar.session_id = s.id and ar.run_number = 1;
-- A legacy job can be marked completed even if its result row was lost. It
-- cannot become a published run, because there is no report to preserve.
update public.analysis_jobs j set status = 'failed', error_code = 'missing_result',
  error_message = 'The completed job has no stored result.', updated_at = now()
where j.status = 'completed' and not exists
  (select 1 from public.analysis_results r where r.job_id = j.id);
insert into public.analysis_runs(owner_id, session_id, video_asset_id, job_id, run_number,
  status, params, created_at, started_at, error_code, error_message)
select j.owner_id, j.session_id, j.video_asset_id, j.id,
  case when ar.id is null then 1 else 2 end, j.status, j.params,
  j.created_at, j.started_at, j.error_code, j.error_message
from public.analysis_jobs j left join public.analysis_runs ar on ar.job_id = j.id and ar.run_number = 1
where ar.id is null or j.status <> 'completed';
update public.analysis_jobs j set current_run_id = ar.id
from public.analysis_runs ar where ar.job_id = j.id
  and ar.run_number = (select max(run_number) from public.analysis_runs where job_id = j.id);

-- Metric rows are reserved for quality-gated revision-4 measurements. The
-- current whole-clip prototype does not insert rows or seed baselines here.
create table public.metric_results (
  run_id uuid not null references public.analysis_runs(id) on delete cascade,
  participant_id uuid not null references public.session_participants(id) on delete cascade,
  metric_key text not null,
  definition_version text not null,
  validation_level text not null default 'not_evaluated'
    check (validation_level in ('not_evaluated', 'synthetic_only', 'evaluated_on_real_footage')),
  quality_status text not null check (quality_status in ('available', 'insufficient_coverage', 'unvalidated', 'unavailable')),
  value numeric,
  numerator numeric,
  denominator numeric,
  valid_s numeric check (valid_s is null or valid_s >= 0),
  evaluable_s numeric check (evaluable_s is null or evaluable_s >= 0),
  contact_count integer check (contact_count is null or contact_count >= 0),
  quality_details jsonb not null default '{}'::jsonb check (jsonb_typeof(quality_details) = 'object'),
  primary key (run_id, participant_id, metric_key),
  check ((quality_status = 'available' and validation_level = 'evaluated_on_real_footage' and value is not null)
    or (quality_status <> 'available' and value is null)),
  check (valid_s is null or evaluable_s is null or valid_s <= evaluable_s)
);
create function public.require_metric_run_participant() returns trigger
language plpgsql security definer set search_path = '' as $$
declare run_session uuid; participant_session uuid; run_version text;
begin
  select session_id, metric_definition_version into run_session, run_version
    from public.analysis_runs where id = new.run_id;
  select session_id into participant_session from public.session_participants where id = new.participant_id;
  if run_session is distinct from participant_session or new.definition_version <> run_version then
    raise exception 'metric_run_participant_mismatch' using errcode = '22023';
  end if;
  return new;
end $$;
create trigger metric_run_participant before insert or update on public.metric_results
  for each row execute function public.require_metric_run_participant();
revoke all on function public.require_metric_run_participant() from public, anon, authenticated;
alter table public.metric_results enable row level security;
create policy metric_results_self on public.metric_results for select to authenticated
  using (exists (select 1 from public.session_participants p
    where p.id = participant_id and p.player_id = (select auth.uid())));
revoke all on public.metric_results from anon, authenticated;
grant select on public.metric_results to authenticated;
grant all on public.metric_results to service_role;

create or replace function public.finalize_video_upload(p_video_id uuid, p_params jsonb default '{}'::jsonb)
returns public.analysis_jobs language plpgsql security definer set search_path = '' as $$
declare v public.video_assets; j public.analysis_jobs; obj_size bigint;
begin
  if p_params is null or jsonb_typeof(p_params) <> 'object' then
    raise exception 'invalid_params' using errcode = '22023';
  end if;
  select * into v from public.video_assets where id = p_video_id and owner_id = auth.uid() for update;
  if not found then raise exception 'video_not_found' using errcode = 'P0002'; end if;
  if v.upload_status = 'pending' then
    select (o.metadata ->> 'size')::bigint into obj_size from storage.objects o
      where o.bucket_id = v.storage_bucket and o.name = v.storage_path;
    if not found then raise exception 'upload_incomplete' using errcode = 'P0001'; end if;
    update public.video_assets set upload_status = 'uploaded', uploaded_at = now(),
      byte_size = coalesce(obj_size, byte_size) where id = v.id;
  end if;
  insert into public.analysis_jobs(owner_id, video_asset_id, session_id, params)
  values (v.owner_id, v.id, v.session_id, p_params) on conflict (video_asset_id) do nothing;
  select * into j from public.analysis_jobs where video_asset_id = v.id for update;
  if j.current_run_id is null then
    if j.status = 'completed' then
      raise exception 'completed_job_missing_run' using errcode = 'P0001';
    end if;
    insert into public.analysis_runs(owner_id, session_id, video_asset_id, job_id, run_number, status, params)
    values (j.owner_id, j.session_id, j.video_asset_id, j.id, 1, j.status, j.params)
    returning id into j.current_run_id;
    update public.analysis_jobs set current_run_id = j.current_run_id where id = j.id;
  end if;
  return j;
end $$;

create or replace function public.request_reanalysis(p_job_id uuid, p_params jsonb default null)
returns public.analysis_jobs language plpgsql security definer set search_path = '' as $$
declare j public.analysis_jobs; next_run uuid; n integer;
begin
  if p_params is not null and jsonb_typeof(p_params) <> 'object' then
    raise exception 'invalid_params' using errcode = '22023';
  end if;
  select * into j from public.analysis_jobs where id = p_job_id and owner_id = auth.uid() for update;
  if not found then raise exception 'job_not_found' using errcode = 'P0002'; end if;
  if j.status not in ('completed', 'failed') then
    raise exception 'job_not_finished' using errcode = 'P0001';
  end if;
  select coalesce(max(run_number), 0) + 1 into n from public.analysis_runs where session_id = j.session_id;
  insert into public.analysis_runs(owner_id, session_id, video_asset_id, job_id, run_number, status, params)
  values (j.owner_id, j.session_id, j.video_asset_id, j.id, n, 'queued', coalesce(p_params, j.params))
  returning id into next_run;
  update public.analysis_jobs set status = 'queued', attempts = 0, available_at = now(),
    params = coalesce(p_params, params), current_run_id = next_run,
    error_code = null, error_message = null, locked_by = null, lease_expires_at = null,
    started_at = null, finished_at = null, updated_at = now()
    where id = j.id returning * into j;
  return j;
end $$;

create or replace function public.claim_analysis_job(p_worker_id text, p_lease_seconds int default 300)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare j public.analysis_jobs; v public.video_assets;
begin
  update public.analysis_jobs set status = 'failed', locked_by = null, lease_expires_at = null,
    finished_at = now(), updated_at = now(), error_code = 'lease_expired',
    error_message = 'The worker stopped responding on the final attempt.'
    where status = 'processing' and lease_expires_at < now() and attempts >= max_attempts;
  update public.analysis_runs ar set status = 'failed', error_code = 'lease_expired',
    error_message = 'The worker stopped responding on the final attempt.'
    from public.analysis_jobs aj where aj.current_run_id = ar.id and aj.status = 'failed'
      and aj.error_code = 'lease_expired' and ar.status = 'processing';
  select * into j from public.analysis_jobs
    where (status = 'queued' and available_at <= now())
       or (status = 'processing' and lease_expires_at < now())
    order by available_at, created_at for update skip locked limit 1;
  if not found then return null; end if;
  update public.analysis_jobs set status = 'processing', locked_by = p_worker_id,
    attempts = attempts + 1, lease_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)),
    started_at = coalesce(started_at, now()), updated_at = now()
    where id = j.id returning * into j;
  update public.analysis_runs set status = 'processing', started_at = coalesce(started_at, now())
    where id = j.current_run_id;
  select * into v from public.video_assets where id = j.video_asset_id;
  return jsonb_build_object('id', j.id, 'run_id', j.current_run_id, 'owner_id', j.owner_id,
    'video_asset_id', j.video_asset_id, 'session_id', j.session_id,
    'storage_bucket', v.storage_bucket, 'storage_path', v.storage_path,
    'original_filename', v.original_filename, 'attempts', j.attempts,
    'max_attempts', j.max_attempts, 'params', j.params);
end $$;

create or replace function public.complete_analysis_job(p_job_id uuid, p_worker_id text, p_result jsonb)
returns void language plpgsql security definer set search_path = '' as $$
declare j public.analysis_jobs;
begin
  j := public._lock_held_job(p_job_id, p_worker_id);
  if p_result ->> 'schema_version' is null
    or coalesce(p_result ->> 'status', '') not in ('ok', 'insufficient_data')
    or coalesce(p_result ->> 'data_origin', '') not in ('measured', 'test_fixture')
    or p_result #>> '{provenance,pipeline_version}' is null then
    raise exception 'invalid_result' using errcode = '22023';
  end if;
  update public.analysis_runs set status = 'completed', result = p_result,
    result_schema_version = p_result ->> 'schema_version', result_status = p_result ->> 'status',
    pipeline_version = p_result #>> '{provenance,pipeline_version}',
    source_sha256 = p_result #>> '{provenance,source,sha256}',
    model_versions = jsonb_build_object('player_detector', p_result #>> '{provenance,detector,name}',
      'ball_detector', p_result #>> '{provenance,ball_detector,name}'),
    completed_at = now(), published_at = now(), error_code = null, error_message = null
    where id = j.current_run_id and status = 'processing';
  if not found then raise exception 'run_not_processing' using errcode = 'P0001'; end if;
  update public.sessions set active_run_id = j.current_run_id where id = j.session_id;
  -- Compatibility row for current clients; immutable reports remain in analysis_runs.
  insert into public.analysis_results(job_id, owner_id, session_id, video_asset_id, run_id,
    schema_version, result_status, data_origin, pipeline_version,
    analyzed_duration_s, video_duration_s, fraction_analyzed, result)
  values (j.id, j.owner_id, j.session_id, j.video_asset_id, j.current_run_id,
    p_result ->> 'schema_version', p_result ->> 'status', p_result ->> 'data_origin',
    p_result #>> '{provenance,pipeline_version}',
    (p_result #>> '{coverage,analyzed_duration_s}')::double precision,
    (p_result #>> '{video,container_duration_s}')::double precision,
    (p_result #>> '{coverage,fraction_of_video_analyzed}')::double precision, p_result)
  on conflict (job_id) do update set run_id = excluded.run_id,
    schema_version = excluded.schema_version, result_status = excluded.result_status,
    data_origin = excluded.data_origin, pipeline_version = excluded.pipeline_version,
    analyzed_duration_s = excluded.analyzed_duration_s, video_duration_s = excluded.video_duration_s,
    fraction_analyzed = excluded.fraction_analyzed, result = excluded.result, created_at = now();
  update public.analysis_jobs set status = 'completed', locked_by = null,
    lease_expires_at = null, error_code = null, error_message = null,
    finished_at = now(), updated_at = now() where id = j.id;
end $$;

create or replace function public.fail_analysis_job(p_job_id uuid, p_worker_id text,
  p_error_code text, p_error_message text, p_retryable boolean)
returns text language plpgsql security definer set search_path = '' as $$
declare j public.analysis_jobs; new_status text;
begin
  j := public._lock_held_job(p_job_id, p_worker_id);
  new_status := case when p_retryable and j.attempts < j.max_attempts then 'queued' else 'failed' end;
  update public.analysis_jobs set status = new_status, locked_by = null, lease_expires_at = null,
    error_code = left(p_error_code, 64), error_message = left(p_error_message, 2000),
    available_at = case when new_status = 'queued'
      then now() + make_interval(secs => 30 * power(2, greatest(j.attempts - 1, 0)))
      else available_at end,
    finished_at = case when new_status = 'failed' then now() else null end,
    updated_at = now() where id = j.id;
  update public.analysis_runs set status = new_status, error_code = left(p_error_code, 64),
    error_message = left(p_error_message, 2000) where id = j.current_run_id;
  return new_status;
end $$;


-- ════════════════ 20260929142117_raw_video_retention.sql ════════════════

-- The raw recording expires 30 days after its first measured analysis.
-- Results remain available after Storage deletes the original file.
alter table public.video_assets
  add column raw_video_expires_at timestamptz,
  add column raw_video_kept boolean not null default false,
  add column raw_video_deleting_at timestamptz,
  add column raw_video_deleted_at timestamptz;

create index video_assets_expiry_idx on public.video_assets (raw_video_expires_at)
  where raw_video_deleted_at is null and raw_video_kept = false;

create function public.set_raw_video_expiry_after_result()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.status = 'completed' and old.status is distinct from 'completed'
     and new.result ->> 'data_origin' = 'measured' then
    update public.video_assets
      set raw_video_expires_at = coalesce(raw_video_expires_at, now() + interval '30 days')
      where id = new.video_asset_id and raw_video_deleted_at is null;
  end if;
  return new;
end $$;

create trigger analysis_run_sets_raw_video_expiry
  after update of status on public.analysis_runs
  for each row execute function public.set_raw_video_expiry_after_result();

-- Existing measured reports start their retention clock at this migration.
update public.video_assets v
set raw_video_expires_at = now() + interval '30 days'
where v.raw_video_expires_at is null
  and exists (select 1 from public.analysis_runs r
    where r.video_asset_id = v.id and r.status = 'completed'
      and r.result ->> 'data_origin' = 'measured');

create function public.set_raw_video_keep(p_video_id uuid, p_keep boolean)
returns public.video_assets language plpgsql security definer set search_path = '' as $$
declare v public.video_assets;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v from public.video_assets where id = p_video_id and owner_id = auth.uid() for update;
  if not found then raise exception 'video_not_found' using errcode = 'P0002'; end if;
  if v.raw_video_deleted_at is not null or v.raw_video_deleting_at is not null then
    raise exception 'raw_video_deletion_started' using errcode = 'P0001';
  end if;
  update public.video_assets set raw_video_kept = p_keep where id = p_video_id returning * into v;
  return v;
end $$;

-- A trusted worker claims one expired object. A one-hour lease permits retry
-- after a crash; the UI cannot alter a video once deletion has begun.
create function public.claim_expired_raw_video()
returns table (id uuid, storage_bucket text, storage_path text)
language plpgsql security invoker set search_path = '' as $$
declare v public.video_assets;
begin
  select * into v from public.video_assets a
    where a.raw_video_expires_at <= now() and a.raw_video_kept = false
      and a.raw_video_deleted_at is null
      and (a.raw_video_deleting_at is null or a.raw_video_deleting_at < now() - interval '1 hour')
      and not exists (select 1 from public.analysis_jobs j
        where j.video_asset_id = a.id and j.status in ('queued', 'processing'))
    order by a.raw_video_expires_at, a.id for update skip locked limit 1;
  if not found then return; end if;
  update public.video_assets set raw_video_deleting_at = now() where video_assets.id = v.id;
  return query select v.id, v.storage_bucket, v.storage_path;
end $$;

create function public.complete_raw_video_deletion(p_video_id uuid)
returns void language plpgsql security invoker set search_path = '' as $$
begin
  update public.video_assets
    set raw_video_deleted_at = now(), raw_video_deleting_at = null
    where id = p_video_id and raw_video_deleting_at is not null
      and raw_video_deleted_at is null;
end $$;

create function public.reject_reanalysis_after_raw_video_deletion()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.status = 'queued' and old.status is distinct from 'queued'
     and exists (select 1 from public.video_assets v
       where v.id = new.video_asset_id
         and (v.raw_video_deleted_at is not null or v.raw_video_deleting_at is not null)) then
    raise exception 'raw_video_expired' using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger analysis_jobs_reject_expired_reanalysis
  before update of status on public.analysis_jobs
  for each row execute function public.reject_reanalysis_after_raw_video_deletion();

revoke all on function public.set_raw_video_expiry_after_result() from public, anon, authenticated;
revoke all on function public.set_raw_video_keep(uuid, boolean) from public, anon;
grant execute on function public.set_raw_video_keep(uuid, boolean) to authenticated;
revoke all on function public.claim_expired_raw_video() from public, anon, authenticated;
grant execute on function public.claim_expired_raw_video() to service_role;
revoke all on function public.complete_raw_video_deletion(uuid) from public, anon, authenticated;
grant execute on function public.complete_raw_video_deletion(uuid) to service_role;
revoke all on function public.reject_reanalysis_after_raw_video_deletion() from public, anon, authenticated;


-- ════════════════ 20260929200000_dev_mock_runs.sql ════════════════

-- Dev-mode mock data must look like a normal published report since the
-- versioned-run migration: each mock job gets run 1, the job points to it as
-- its current run, and the session publishes it as the active report. Without
-- this, mock sessions have an empty run history and no active report.
--
-- Same limits as before: anonymous callers only, only the caller's own rows,
-- every result marked provenance.pipeline_version = 'dev-mock', and reseeding
-- replaces the caller's earlier '[Dev mock]' sessions.

create or replace function public.seed_dev_mock_data(p_sessions jsonb)
returns int
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  s jsonb;
  r jsonb;
  v_session uuid;
  v_video uuid;
  v_job uuid;
  v_run uuid;
  n int := 0;
begin
  if uid is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) is not true then
    raise exception 'dev_mock_requires_anonymous_user' using errcode = '42501',
      hint = 'Mock data can only be created for a Dev mode (anonymous) sign-in.';
  end if;
  if p_sessions is null or jsonb_typeof(p_sessions) <> 'array'
     or jsonb_array_length(p_sessions) not between 1 and 10 then
    raise exception 'invalid_mock_sessions' using errcode = '22023';
  end if;

  -- Replace, not accumulate. Cascades remove videos, jobs, runs and results.
  delete from public.sessions where owner_id = uid and title like '[Dev mock]%';

  for s in select * from jsonb_array_elements(p_sessions) loop
    r := s -> 'result';
    if r ->> 'schema_version' is null
       or coalesce(r ->> 'status', '') not in ('ok', 'insufficient_data')
       or coalesce(r ->> 'data_origin', '') not in ('measured', 'test_fixture')
       or r #>> '{provenance,pipeline_version}' is distinct from 'dev-mock' then
      raise exception 'invalid_mock_result' using errcode = '22023',
        hint = 'Mock results must be valid v1 results with provenance.pipeline_version = dev-mock.';
    end if;

    insert into public.sessions (owner_id, title, session_date, session_context, play_format, notes)
    values (uid, '[Dev mock] ' || left(coalesce(s ->> 'title', 'Session'), 100),
            coalesce((s ->> 'session_date')::date, current_date),
            coalesce(s ->> 'session_context', 'practice'), coalesce(s ->> 'play_format', 'singles'),
            'Generated by Dev mode. Not an analysis of a real video.')
    returning id into v_session;

    v_video := gen_random_uuid();
    insert into public.video_assets (id, owner_id, session_id, storage_path, original_filename, mime_type,
                                     byte_size, upload_status, uploaded_at)
    values (v_video, uid, v_session, uid || '/' || v_session || '/' || v_video || '.mp4',
            'dev_mock_' || (n + 1) || '.mp4', 'video/mp4', 1, 'uploaded', now());

    insert into public.analysis_jobs (owner_id, video_asset_id, session_id, status, attempts, started_at, finished_at)
    values (uid, v_video, v_session, 'completed', 1, now(), now())
    returning id into v_job;

    -- Inserted already completed, so the raw-video expiry trigger (which only
    -- fires on a status update) does not schedule deletion of a file that
    -- does not exist.
    insert into public.analysis_runs (owner_id, session_id, video_asset_id, job_id, run_number, status,
      pipeline_version, result_schema_version, result_status, result, started_at, completed_at, published_at)
    values (uid, v_session, v_video, v_job, 1, 'completed', 'dev-mock', r ->> 'schema_version',
            r ->> 'status', r, now(), now(), now())
    returning id into v_run;

    update public.analysis_jobs set current_run_id = v_run where id = v_job;
    update public.sessions set active_run_id = v_run where id = v_session;

    insert into public.analysis_results (
      job_id, owner_id, session_id, video_asset_id, run_id, schema_version, result_status, data_origin,
      pipeline_version, analyzed_duration_s, video_duration_s, fraction_analyzed, result)
    values (
      v_job, uid, v_session, v_video, v_run, r ->> 'schema_version', r ->> 'status', r ->> 'data_origin', 'dev-mock',
      (r #>> '{coverage,analyzed_duration_s}')::double precision,
      (r #>> '{video,container_duration_s}')::double precision,
      (r #>> '{coverage,fraction_of_video_analyzed}')::double precision,
      r);
    n := n + 1;
  end loop;
  return n;
end $$;

revoke all on function public.seed_dev_mock_data(jsonb) from public, anon, authenticated;
grant execute on function public.seed_dev_mock_data(jsonb) to authenticated;


-- ════════════════ 20260930090000_analysis_progress.sql ════════════════

-- Progress of a running analysis, for the progress bar on the session page.
-- Only the worker that holds the job's lease can write it (through
-- update_analysis_progress); owners read it with the rest of the job row.

alter table public.analysis_jobs
  add column progress real check (progress between 0 and 1),
  add column progress_stage text check (progress_stage in ('downloading', 'checking', 'analyzing', 'finishing')),
  add column progress_updated_at timestamptz;

comment on column public.analysis_jobs.progress is
  'Share of the analysis done (0-1) while processing; 1 when completed; null otherwise.';

-- A status change or a new worker starts the bar over (claim, retry, re-analysis, a
-- takeover after a worker stopped responding) or fills it (completed).
create function public.reset_analysis_progress()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.status is distinct from old.status or new.locked_by is distinct from old.locked_by then
    new.progress := case when new.status = 'completed' then 1 else null end;
    new.progress_stage := null;
    new.progress_updated_at := case when new.status = 'completed' then now() else null end;
  end if;
  return new;
end $$;

create trigger analysis_jobs_reset_progress
  before update of status, locked_by on public.analysis_jobs
  for each row execute function public.reset_analysis_progress();

create function public.update_analysis_progress(p_job_id uuid, p_worker_id text, p_progress real, p_stage text)
returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  if p_stage not in ('downloading', 'checking', 'analyzing', 'finishing') then
    raise exception 'unknown progress stage: %', p_stage using errcode = '22023';
  end if;
  update public.analysis_jobs
     set progress = greatest(0, least(1, coalesce(p_progress, 0))), progress_stage = p_stage,
         progress_updated_at = now()
   where id = p_job_id and status = 'processing' and locked_by = p_worker_id and lease_expires_at >= now();
  return found;
end $$;

-- Supabase grants EXECUTE on new public functions to anon/authenticated by default.
revoke all on function public.reset_analysis_progress() from public, anon, authenticated;
revoke all on function public.update_analysis_progress(uuid, text, real, text) from public, anon, authenticated;
grant execute on function public.update_analysis_progress(uuid, text, real, text) to service_role;


-- ════════════════ 20261006090000_self_assessment.sql ════════════════

-- Self-assessment path: a session can be reviewed from the player's own
-- ratings, without uploading a video. Video analysis stays available as an
-- optional extra on any session. Safe to run more than once (for example by
-- pasting it into the Supabase SQL editor of an existing project).

alter table public.sessions
  add column if not exists review_mode text not null default 'video'
    check (review_mode in ('self', 'video'));

-- Ratings are 1-5 per skill. Keys must match SELF_SKILLS in
-- src/lib/coaching/selfAssessment.ts.
create or replace function public.valid_self_ratings(r jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(r) = 'object' and not exists (
    select 1 from jsonb_each(r) e
    where e.key not in ('serve', 'return', 'third_shot', 'dinking', 'volleys',
                        'kitchen_line', 'transition', 'footwork', 'consistency', 'strategy')
       or jsonb_typeof(e.value) <> 'number'
       or e.value::text not in ('1', '2', '3', '4', '5')
  )
$$;

create table if not exists public.self_assessments (
  session_id uuid primary key references public.sessions(id) on delete cascade,
  owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  ratings jsonb not null default '{}'::jsonb check (public.valid_self_ratings(ratings)),
  -- Optional rough counts from the player's memory of the session.
  games_played smallint check (games_played between 0 and 50),
  games_won smallint check (games_won between 0 and 50),
  unforced_errors text check (unforced_errors in ('few', 'some', 'many')),
  biggest_struggle text check (char_length(biggest_struggle) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (games_won is null or games_played is null or games_won <= games_played)
);
create index if not exists self_assessments_owner_idx on public.self_assessments (owner_id);

create or replace function public.touch_self_assessment() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' then new.created_at := old.created_at; end if;
  return new;
end $$;
drop trigger if exists self_assessment_touch on public.self_assessments;
create trigger self_assessment_touch before insert or update on public.self_assessments
  for each row execute function public.touch_self_assessment();

alter table public.self_assessments enable row level security;
drop policy if exists self_assessments_own on public.self_assessments;
create policy self_assessments_own on public.self_assessments for all to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid())
    and exists (select 1 from public.sessions s where s.id = session_id and s.owner_id = (select auth.uid())));

revoke all on public.self_assessments from anon, authenticated;
grant select, insert, update, delete on public.self_assessments to authenticated;


-- ════════════════ 20261006100000_player_onboarding.sql ════════════════

-- "Getting to know the player" at account creation. Answers live on the
-- player's private profile and seed a starting practice plan before any
-- session is logged. Safe to run more than once.
-- Needs 20261006090000_self_assessment.sql (valid_self_ratings).

alter table public.profiles
  add column if not exists play_frequency text
    check (play_frequency in ('first_time', 'monthly', 'weekly', 'few_per_week', 'daily')),
  add column if not exists play_reasons text[] not null default '{}'::text[]
    check (play_reasons <@ array['fun', 'fitness', 'social', 'compete', 'tournaments']::text[]),
  add column if not exists main_goals text[] not null default '{}'::text[]
    check (main_goals <@ array['positioning', 'shot_outcomes', 'shot_technique']::text[]),
  -- The player's usual level per skill, same keys and 1-5 scale as self_assessments.ratings.
  add column if not exists baseline_ratings jsonb not null default '{}'::jsonb
    check (public.valid_self_ratings(baseline_ratings)),
  add column if not exists onboarding_completed_at timestamptz;


-- ════════════════ 20261006110000_adviser_notes.sql ════════════════

-- Adviser notes (6 Oct 2026): default settings, tournament and solo sessions,
-- named players, and limits on video uploads. Safe to run more than once.

-- ── Default settings for new sessions ────────────────────────────────────
alter table public.profiles
  add column if not exists default_review_mode text check (default_review_mode in ('self', 'video')),
  add column if not exists default_session_kind text check (default_session_kind in ('solo', 'match', 'tournament')),
  add column if not exists default_play_format text
    check (default_play_format in ('singles', 'doubles', 'wall_practice', 'ball_machine', 'drill_other'));

-- ── Tournament details ───────────────────────────────────────────────────
alter table public.sessions
  add column if not exists tournament_name text check (char_length(btrim(tournament_name)) between 1 and 120),
  add column if not exists tournament_round text check (char_length(btrim(tournament_round)) between 1 and 60),
  add column if not exists match_result text check (match_result in ('win', 'loss')),
  add column if not exists match_score text check (char_length(btrim(match_score)) between 1 and 40);

-- ── Named partners and opponents ─────────────────────────────────────────
-- Other players are names typed by the session owner; they are not linked
-- to accounts and are visible only to the owner.
alter table public.session_participants
  add column if not exists display_name text check (char_length(btrim(display_name)) between 1 and 80);

drop policy if exists participants_owner_manage on public.session_participants;
create policy participants_owner_manage on public.session_participants for all to authenticated
  using (role in ('partner', 'opponent') and player_id is null
    and exists (select 1 from public.sessions s where s.id = session_id and s.owner_id = (select auth.uid())))
  with check (role in ('partner', 'opponent') and player_id is null and link_status = 'anonymous'
    and exists (select 1 from public.sessions s where s.id = session_id and s.owner_id = (select auth.uid())));
grant insert, update, delete on public.session_participants to authenticated;

-- ── Video upload limits ──────────────────────────────────────────────────
-- One place for the limits; the web app reads them with rpc('video_upload_limits').
create or replace function public.video_upload_limits() returns jsonb
language sql immutable set search_path = '' as $$
  select jsonb_build_object(
    'max_file_bytes', 50000000,        -- 50 MB per video (matches the storage bucket)
    'min_duration_s', 10,              -- long enough to see a rally
    'max_duration_s', 300,             -- 5 minutes per clip
    'max_total_bytes', 1000000000,     -- 1 GB of stored raw video per player
    'max_uploads_per_day', 5)
$$;
grant execute on function public.video_upload_limits() to authenticated;

alter table public.video_assets
  add column if not exists duration_s numeric(7,2) check (duration_s > 0);

create or replace function public.enforce_video_upload_limits() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  lim jsonb := public.video_upload_limits();
  used bigint;
  today int;
begin
  if new.byte_size > (lim->>'max_file_bytes')::bigint then
    raise exception 'video_too_large' using errcode = '22023';
  end if;
  -- Older web builds do not send a duration; the limit applies when it is known.
  if new.duration_s is not null and (new.duration_s < (lim->>'min_duration_s')::numeric
      or new.duration_s > (lim->>'max_duration_s')::numeric) then
    raise exception 'video_duration_out_of_range' using errcode = '22023';
  end if;
  select coalesce(sum(v.byte_size), 0), count(*) filter (where v.created_at > now() - interval '1 day')
    into used, today
    from public.video_assets v
    where v.owner_id = new.owner_id and v.raw_video_deleted_at is null;
  if used + new.byte_size > (lim->>'max_total_bytes')::bigint then
    raise exception 'video_storage_quota_exceeded' using errcode = '22023';
  end if;
  if today >= (lim->>'max_uploads_per_day')::int then
    raise exception 'video_daily_limit_reached' using errcode = '22023';
  end if;
  return new;
end $$;
revoke all on function public.enforce_video_upload_limits() from public, anon, authenticated;
drop trigger if exists video_asset_upload_limits on public.video_assets;
create trigger video_asset_upload_limits before insert on public.video_assets
  for each row execute function public.enforce_video_upload_limits();


-- ════════════════ 20261007090000_profile_photos.sql ════════════════

-- Profile editing (7 Oct 2026): profile photo, short bio, home court and
-- paddle. Profiles stay private to their owner, and photos live in a
-- private bucket inside the owner's folder. Safe to run more than once.

alter table public.profiles
  add column if not exists avatar_path text,
  add column if not exists bio text check (char_length(bio) <= 160),
  add column if not exists home_court text check (char_length(btrim(home_court)) between 1 and 80),
  add column if not exists paddle text check (char_length(btrim(paddle)) between 1 and 60);

-- The photo path must point into the owner's own folder of the photo bucket.
alter table public.profiles drop constraint if exists profiles_avatar_path_own;
alter table public.profiles add constraint profiles_avatar_path_own
  check (avatar_path is null or avatar_path ~ ('^' || id::text || '/avatar-[0-9]+\.(webp|jpg)$'));

-- ── Private photo bucket ─────────────────────────────────────────────────
-- The app shrinks photos to 512 px before upload, so 2 MB is plenty.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('profile-photos', 'profile-photos', false, 2000000, array['image/webp', 'image/jpeg'])
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists profile_photos_select_own on storage.objects;
create policy profile_photos_select_own on storage.objects for select to authenticated
  using (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists profile_photos_insert_own on storage.objects;
create policy profile_photos_insert_own on storage.objects for insert to authenticated
  with check (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists profile_photos_update_own on storage.objects;
create policy profile_photos_update_own on storage.objects for update to authenticated
  using (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists profile_photos_delete_own on storage.objects;
create policy profile_photos_delete_own on storage.objects for delete to authenticated
  using (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);


-- ════════════════ 20261022090000_buddy_finder.sql ════════════════

-- Buddy finder (requirements N01-N05, as scoped by the team on 22 Oct 2026).
-- Players who opt in are listed with their name and level (beginner, novice,
-- intermediate, advanced). Another player sends a buddy request with a
-- purpose, a format and the dates and times they are free; the receiver
-- accepts or declines. No booking, payments or public game listings (N04).
-- Safe to run more than once.

-- ── Opt-in ───────────────────────────────────────────────────────────────
-- Off by default: nobody is listed until they choose to be (N01, N05).
alter table public.profiles add column if not exists buddy_visible boolean not null default false;

-- ── Levels ───────────────────────────────────────────────────────────────
-- The profile stores the level as text. Earlier versions of the app offered
-- "New to the game", "Beginner (2.0-2.5)", "Intermediate (3.0-3.5)" and
-- "Advanced (4.0+)"; they map onto the four buddy levels here.
create or replace function public.buddy_level(p_level text) returns text
language sql immutable set search_path = '' as $$
  select case
    when p_level is null then null
    when lower(p_level) like '%advanced%' then 'advanced'
    when lower(p_level) like '%intermediate%' then 'intermediate'
    when lower(p_level) like '%novice%' then 'novice'
    when lower(p_level) like '%beginner%' or lower(p_level) like '%new to%' then 'beginner'
    else null
  end
$$;

-- ── Requests ─────────────────────────────────────────────────────────────
create table if not exists public.buddy_requests (
  id uuid primary key default gen_random_uuid(),
  from_player_id uuid not null references public.profiles (id) on delete cascade,
  to_player_id uuid not null references public.profiles (id) on delete cascade,
  purpose text not null check (purpose in ('practice', 'casual_game', 'competition')),
  play_format text not null check (play_format in ('singles', 'doubles', 'either')),
  -- [{"date": "YYYY-MM-DD", "start": "HH:MM", "end": "HH:MM"}, ...]; checked by buddy_slots_valid.
  slots jsonb not null,
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'cancelled')),
  created_at timestamptz not null default now(),
  responded_at timestamptz,
  constraint buddy_requests_not_self check (from_player_id <> to_player_id)
);
-- One open request per pair of players, whichever of them sent it.
create unique index if not exists buddy_requests_one_pending on public.buddy_requests
  (least(from_player_id, to_player_id), greatest(from_player_id, to_player_id)) where status = 'pending';
create index if not exists buddy_requests_to_status on public.buddy_requests (to_player_id, status);
create index if not exists buddy_requests_from_status on public.buddy_requests (from_player_id, status);

alter table public.buddy_requests enable row level security;
drop policy if exists buddy_requests_parties_read on public.buddy_requests;
create policy buddy_requests_parties_read on public.buddy_requests for select to authenticated
  using ((select auth.uid()) in (from_player_id, to_player_id));
-- Rows change only through the functions below, which check every rule.
revoke all on public.buddy_requests from anon, authenticated;
grant select on public.buddy_requests to authenticated;
grant all on public.buddy_requests to service_role;

-- 1 to 10 free times, each a real date from today up to 90 days ahead, with
-- a start before the end.
create or replace function public.buddy_slots_valid(p_slots jsonb) returns boolean
language plpgsql stable set search_path = '' as $$
declare
  s jsonb;
  d date;
  t_start time;
  t_end time;
begin
  if p_slots is null or jsonb_typeof(p_slots) <> 'array' or jsonb_array_length(p_slots) not between 1 and 10 then
    return false;
  end if;
  for s in select value from jsonb_array_elements(p_slots) loop
    if jsonb_typeof(s) <> 'object' or s ->> 'date' !~ '^\d{4}-\d{2}-\d{2}$'
       or s ->> 'start' !~ '^\d{2}:\d{2}$' or s ->> 'end' !~ '^\d{2}:\d{2}$' then
      return false;
    end if;
    begin
      d := (s ->> 'date')::date;
      t_start := (s ->> 'start')::time;
      t_end := (s ->> 'end')::time;
    exception when others then
      return false;
    end;
    -- One day of slack for players in time zones ahead of the server.
    if d < current_date - 1 or d > current_date + 90 or t_start >= t_end then
      return false;
    end if;
  end loop;
  return true;
end $$;

-- The caller may use the buddy finder: a signed-in, non-guest player who
-- confirmed being 18 or older (N05).
create or replace function public.buddy_check_caller() returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'buddy: guest accounts cannot use Buddy' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles p where p.id = me and p.is_adult_confirmed) then
    raise exception 'buddy: confirm in your profile that you are 18 or older' using errcode = '42501';
  end if;
  return me;
end $$;

-- Players listed in Buddy, with the latest open or accepted request between
-- the caller and each of them.
create or replace function public.buddy_players()
returns table (player_id uuid, display_name text, level text, usual_format text,
               request_id uuid, request_status text, request_direction text)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  return query
  select p.id, p.display_name, public.buddy_level(p.self_level), p.usual_format,
         r.id, r.status, case when r.id is null then null when r.from_player_id = me then 'outgoing' else 'incoming' end
  from public.profiles p
  join auth.users u on u.id = p.id
  left join lateral (
    select br.id, br.status, br.from_player_id from public.buddy_requests br
    where br.status in ('pending', 'accepted')
      and ((br.from_player_id = me and br.to_player_id = p.id) or (br.from_player_id = p.id and br.to_player_id = me))
    order by (br.status = 'pending') desc, br.created_at desc
    limit 1
  ) r on true
  where p.buddy_visible and p.is_adult_confirmed and not coalesce(u.is_anonymous, false) and p.id <> me
  order by p.display_name
  limit 200;
end $$;

create or replace function public.send_buddy_request(p_to uuid, p_purpose text, p_format text, p_slots jsonb)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
  new_id uuid;
begin
  if not exists (
    select 1 from public.profiles p join auth.users u on u.id = p.id
    where p.id = p_to and p.id <> me and p.buddy_visible and p.is_adult_confirmed and not coalesce(u.is_anonymous, false)
  ) then
    raise exception 'buddy: this player is not available in Buddy' using errcode = 'P0001';
  end if;
  if not public.buddy_slots_valid(p_slots) then
    raise exception 'buddy: add 1 to 10 free times, each with a date in the next 90 days and a start before the end'
      using errcode = '22023';
  end if;
  if (select count(*) from public.buddy_requests where from_player_id = me and status = 'pending') >= 10 then
    raise exception 'buddy: you already have 10 requests waiting for an answer' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.buddy_requests where from_player_id = me and to_player_id = p_to
             and status = 'declined' and responded_at > now() - interval '7 days') then
    raise exception 'buddy: this player declined recently; you can ask again 7 days after their answer' using errcode = 'P0001';
  end if;
  begin
    insert into public.buddy_requests (from_player_id, to_player_id, purpose, play_format, slots)
    values (me, p_to, p_purpose, p_format, p_slots)
    returning id into new_id;
  exception when unique_violation then
    raise exception 'buddy: there is already an open request between you and this player' using errcode = 'P0001';
  end;
  return new_id;
end $$;

create or replace function public.respond_buddy_request(p_request_id uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  update public.buddy_requests
     set status = case when p_accept then 'accepted' else 'declined' end, responded_at = now()
   where id = p_request_id and to_player_id = me and status = 'pending';
  if not found then
    raise exception 'buddy: this request is no longer waiting for your answer' using errcode = 'P0001';
  end if;
end $$;

create or replace function public.cancel_buddy_request(p_request_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  update public.buddy_requests set status = 'cancelled', responded_at = now()
   where id = p_request_id and from_player_id = me and status = 'pending';
  if not found then
    raise exception 'buddy: only a request you sent that is still waiting can be cancelled' using errcode = 'P0001';
  end if;
end $$;

-- Requests the caller sent or received, with the other player's name and level.
-- (20261023090000_buddy_meetup.sql adds the city and location; dropping first
-- lets this file run again after that update, which changes the columns.)
drop function if exists public.my_buddy_requests();
create function public.my_buddy_requests()
returns table (id uuid, direction text, other_player_id uuid, other_name text, other_level text,
               purpose text, play_format text, slots jsonb, status text, created_at timestamptz,
               responded_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  return query
  select r.id, case when r.from_player_id = me then 'outgoing' else 'incoming' end,
         o.id, o.display_name, public.buddy_level(o.self_level),
         r.purpose, r.play_format, r.slots, r.status, r.created_at, r.responded_at
  from public.buddy_requests r
  join public.profiles o on o.id = case when r.from_player_id = me then r.to_player_id else r.from_player_id end
  where me in (r.from_player_id, r.to_player_id) and r.status <> 'cancelled'
  order by r.created_at desc
  limit 100;
end $$;

revoke all on function public.buddy_level(text), public.buddy_slots_valid(jsonb), public.buddy_check_caller(),
  public.buddy_players(), public.send_buddy_request(uuid, text, text, jsonb), public.respond_buddy_request(uuid, boolean),
  public.cancel_buddy_request(uuid), public.my_buddy_requests() from public, anon;
grant execute on function public.buddy_level(text), public.buddy_slots_valid(jsonb), public.buddy_players(),
  public.send_buddy_request(uuid, text, text, jsonb), public.respond_buddy_request(uuid, boolean),
  public.cancel_buddy_request(uuid), public.my_buddy_requests() to authenticated;


-- ════════════════ 20261023090000_buddy_meetup.sql ════════════════

-- Buddy meetup place (team request, 22 Oct 2026): a buddy request also names
-- the city and the court or place to meet, typed by the player.
-- Run AFTER 20261022090000_buddy_finder.sql. Safe to run more than once.

-- Requests sent before this update have no city or location; new ones must have both.
alter table public.buddy_requests
  add column if not exists city text check (char_length(btrim(city)) between 1 and 60),
  add column if not exists location text check (char_length(btrim(location)) between 1 and 120);

-- The request now takes the city and location too.
drop function if exists public.send_buddy_request(uuid, text, text, jsonb);
create or replace function public.send_buddy_request(p_to uuid, p_purpose text, p_format text, p_slots jsonb,
                                                     p_city text, p_location text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
  new_id uuid;
begin
  if not exists (
    select 1 from public.profiles p join auth.users u on u.id = p.id
    where p.id = p_to and p.id <> me and p.buddy_visible and p.is_adult_confirmed and not coalesce(u.is_anonymous, false)
  ) then
    raise exception 'buddy: this player is not available in Buddy' using errcode = 'P0001';
  end if;
  if not public.buddy_slots_valid(p_slots) then
    raise exception 'buddy: add 1 to 10 free times, each with a date in the next 90 days and a start before the end'
      using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_city, ''))) not between 1 and 60 then
    raise exception 'buddy: enter the city (up to 60 characters)' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_location, ''))) not between 1 and 120 then
    raise exception 'buddy: enter where to meet, such as a court name (up to 120 characters)' using errcode = '22023';
  end if;
  if (select count(*) from public.buddy_requests where from_player_id = me and status = 'pending') >= 10 then
    raise exception 'buddy: you already have 10 requests waiting for an answer' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.buddy_requests where from_player_id = me and to_player_id = p_to
             and status = 'declined' and responded_at > now() - interval '7 days') then
    raise exception 'buddy: this player declined recently; you can ask again 7 days after their answer' using errcode = 'P0001';
  end if;
  begin
    insert into public.buddy_requests (from_player_id, to_player_id, purpose, play_format, slots, city, location)
    values (me, p_to, p_purpose, p_format, p_slots, btrim(p_city), btrim(p_location))
    returning id into new_id;
  exception when unique_violation then
    raise exception 'buddy: there is already an open request between you and this player' using errcode = 'P0001';
  end;
  return new_id;
end $$;

-- The request list now includes the city and location.
drop function if exists public.my_buddy_requests();
create function public.my_buddy_requests()
returns table (id uuid, direction text, other_player_id uuid, other_name text, other_level text,
               purpose text, play_format text, slots jsonb, city text, location text, status text,
               created_at timestamptz, responded_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  return query
  select r.id, case when r.from_player_id = me then 'outgoing' else 'incoming' end,
         o.id, o.display_name, public.buddy_level(o.self_level),
         r.purpose, r.play_format, r.slots, r.city, r.location, r.status, r.created_at, r.responded_at
  from public.buddy_requests r
  join public.profiles o on o.id = case when r.from_player_id = me then r.to_player_id else r.from_player_id end
  where me in (r.from_player_id, r.to_player_id) and r.status <> 'cancelled'
  order by r.created_at desc
  limit 100;
end $$;

revoke all on function public.send_buddy_request(uuid, text, text, jsonb, text, text), public.my_buddy_requests() from public, anon;
grant execute on function public.send_buddy_request(uuid, text, text, jsonb, text, text), public.my_buddy_requests() to authenticated;


-- ════════════════ 20261023100000_buddy_cancel.sql ════════════════

-- Cancelling an accepted buddy session (team request, 22 Oct 2026): either
-- player can call it off, with an optional reason the other player sees.
-- Run AFTER 20261023090000_buddy_meetup.sql. Safe to run more than once; if the
-- buddy_finder or buddy_meetup file is run again later, run this one again too
-- (they recreate my_buddy_requests without the cancel columns).

-- "cancelled" stays the sender withdrawing a request that was never answered;
-- "called_off" is an accepted session that one of the two players cancelled.
alter table public.buddy_requests
  add column if not exists cancelled_by uuid references public.profiles (id) on delete set null,
  add column if not exists cancel_reason text check (char_length(cancel_reason) between 1 and 200),
  add column if not exists cancelled_at timestamptz;
alter table public.buddy_requests drop constraint if exists buddy_requests_status_check;
alter table public.buddy_requests add constraint buddy_requests_status_check
  check (status in ('pending', 'accepted', 'declined', 'cancelled', 'called_off'));

create or replace function public.cancel_buddy_session(p_request_id uuid, p_reason text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  reason text := nullif(btrim(coalesce(p_reason, ''), E' \t\r\n'), '');
begin
  -- No 18+ or guest check here: a player can always back out of a session.
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  if char_length(reason) > 200 then
    raise exception 'buddy: keep the reason under 200 characters' using errcode = '22023';
  end if;
  update public.buddy_requests
     set status = 'called_off', cancelled_by = me, cancel_reason = reason, cancelled_at = now()
   where id = p_request_id and me in (from_player_id, to_player_id) and status = 'accepted';
  if not found then
    raise exception 'buddy: only an accepted buddy session can be cancelled' using errcode = 'P0001';
  end if;
end $$;

-- The request list now says who called a session off, and why.
drop function if exists public.my_buddy_requests();
create function public.my_buddy_requests()
returns table (id uuid, direction text, other_player_id uuid, other_name text, other_level text,
               purpose text, play_format text, slots jsonb, city text, location text, status text,
               created_at timestamptz, responded_at timestamptz,
               cancelled_by_me boolean, cancel_reason text, cancelled_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  return query
  select r.id, case when r.from_player_id = me then 'outgoing' else 'incoming' end,
         o.id, o.display_name, public.buddy_level(o.self_level),
         r.purpose, r.play_format, r.slots, r.city, r.location, r.status, r.created_at, r.responded_at,
         r.cancelled_by = me, r.cancel_reason, r.cancelled_at
  from public.buddy_requests r
  join public.profiles o on o.id = case when r.from_player_id = me then r.to_player_id else r.from_player_id end
  where me in (r.from_player_id, r.to_player_id) and r.status <> 'cancelled'
  order by r.created_at desc
  limit 100;
end $$;

revoke all on function public.cancel_buddy_session(uuid, text), public.my_buddy_requests() from public, anon;
grant execute on function public.cancel_buddy_session(uuid, text), public.my_buddy_requests() to authenticated;


-- ════════════════ 20261024090000_partners.sql ════════════════

-- Partners and peer coaching (requirements M01-M03, A03-A04; spec R4a, C1).
-- A player links with someone they trust: by a one-time invite code, or from
-- Buddy after an accepted buddy session. The other player must accept, and
-- either player can unlink (M01). Each player chooses which of their own
-- sessions to share with which partner (M02). A partner sees only that
-- session's video report (metrics, heatmap, video) and can leave notes pinned
-- to moments in the video (M03). Goals, ratings, notes, reflections, the
-- practice plan and audio are never shared. Unlinking removes every share
-- between the two players; signed video links last 5 minutes (A04).
-- Run AFTER 20261023100000_buddy_cancel.sql. Safe to run more than once.

-- ── Links ────────────────────────────────────────────────────────────────
create table if not exists public.partners (
  id uuid primary key default gen_random_uuid(),
  inviter_id uuid not null references public.profiles (id) on delete cascade,
  -- Empty until someone uses the invite code.
  invitee_id uuid references public.profiles (id) on delete cascade,
  -- 8 characters without look-alikes (no I, O, 0 or 1).
  invite_code text unique check (invite_code ~ '^[A-HJ-NP-Z2-9]{8}$'),
  status text not null default 'pending' check (status in ('pending', 'active', 'declined', 'cancelled', 'ended')),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '7 days',
  linked_at timestamptz,
  ended_at timestamptz,
  ended_by uuid references public.profiles (id) on delete set null,
  constraint partners_not_self check (inviter_id <> invitee_id),
  constraint partners_has_target check (invitee_id is not null or invite_code is not null)
);
-- One waiting invite or link per pair of players, whoever sent it.
create unique index if not exists partners_one_open_pair on public.partners
  (least(inviter_id, invitee_id), greatest(inviter_id, invitee_id))
  where status in ('pending', 'active') and invitee_id is not null;
create index if not exists partners_invitee_status on public.partners (invitee_id, status);
create index if not exists partners_inviter_status on public.partners (inviter_id, status);

alter table public.partners enable row level security;
drop policy if exists partners_parties_read on public.partners;
create policy partners_parties_read on public.partners for select to authenticated
  using ((select auth.uid()) in (inviter_id, invitee_id));
-- Rows change only through the functions below.
revoke all on public.partners from anon, authenticated;
grant select on public.partners to authenticated;
grant all on public.partners to service_role;

-- ── Shared sessions ──────────────────────────────────────────────────────
create table if not exists public.report_shares (
  session_id uuid not null references public.sessions (id) on delete cascade,
  owner_id uuid not null references public.profiles (id) on delete cascade,
  partner_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (session_id, partner_id),
  constraint report_shares_not_self check (owner_id <> partner_id)
);
create index if not exists report_shares_partner on public.report_shares (partner_id);

alter table public.report_shares enable row level security;
drop policy if exists report_shares_parties_read on public.report_shares;
create policy report_shares_parties_read on public.report_shares for select to authenticated
  using ((select auth.uid()) in (owner_id, partner_id));
revoke all on public.report_shares from anon, authenticated;
grant select on public.report_shares to authenticated;
grant all on public.report_shares to service_role;

-- ── Peer notes ───────────────────────────────────────────────────────────
create table if not exists public.peer_notes (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions (id) on delete cascade,
  owner_id uuid not null references public.profiles (id) on delete cascade,
  author_id uuid not null references public.profiles (id) on delete cascade,
  -- Seconds into the session's video; empty for a note about the whole session.
  video_time_s numeric(7,2) check (video_time_s between 0 and 36000),
  body text not null check (char_length(btrim(body)) between 1 and 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists peer_notes_session on public.peer_notes (session_id, video_time_s);

-- ── Checks ───────────────────────────────────────────────────────────────
-- A signed-in player with a full account (guest accounts cannot link).
create or replace function public.partner_check_caller() returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'partners: guest accounts cannot link partners; create an account first' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles p where p.id = me) then
    raise exception 'partners: finish setting up your profile first' using errcode = '42501';
  end if;
  return me;
end $$;

create or replace function public.partners_linked(p_a uuid, p_b uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.partners p where p.status = 'active'
    and ((p.inviter_id = p_a and p.invitee_id = p_b) or (p.inviter_id = p_b and p.invitee_id = p_a)))
$$;

-- The caller is a linked partner the session is shared with.
create or replace function public.partner_can_view(p_session_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.report_shares rs
    where rs.session_id = p_session_id and rs.partner_id = auth.uid() and public.partners_linked(rs.owner_id, rs.partner_id))
$$;

-- Used by the storage policy below: the video of a session shared with the caller.
create or replace function public.partner_can_view_video(p_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.video_assets v
    where v.storage_path = p_name and v.upload_status = 'uploaded' and v.raw_video_deleted_at is null
      and public.partner_can_view(v.session_id))
$$;

alter table public.peer_notes enable row level security;
-- Session owners read every note on their sessions; partners read their own
-- notes, and only while the session is still shared with them.
drop policy if exists peer_notes_read on public.peer_notes;
create policy peer_notes_read on public.peer_notes for select to authenticated
  using (owner_id = (select auth.uid())
    or (author_id = (select auth.uid()) and public.partner_can_view(session_id)));
revoke all on public.peer_notes from anon, authenticated;
grant select on public.peer_notes to authenticated;
grant all on public.peer_notes to service_role;

-- A partner may create a short-lived signed link to a shared session's video.
drop policy if exists session_videos_select_partner on storage.objects;
create policy session_videos_select_partner on storage.objects for select to authenticated
  using (bucket_id = 'session-videos' and public.partner_can_view_video(name));

-- ── Linking ──────────────────────────────────────────────────────────────
create or replace function public.partner_limit_check(p_player uuid) returns void
language plpgsql stable security definer set search_path = '' as $$
begin
  if (select count(*) from public.partners p where p.status = 'active' and p_player in (p.inviter_id, p.invitee_id)) >= 20 then
    raise exception 'partners: a player can have at most 20 partners' using errcode = 'P0001';
  end if;
end $$;

-- A one-time code to send to someone, valid for 7 days.
create or replace function public.create_partner_invite()
returns table (id uuid, invite_code text, expires_at timestamptz)
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare
  me uuid := public.partner_check_caller();
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  b bytea;
  code text;
  i int;
  new_id uuid;
begin
  if (select count(*) from public.partners p
      where p.inviter_id = me and p.invitee_id is null and p.status = 'pending' and p.expires_at > now()) >= 3 then
    raise exception 'partners: you already have 3 unused invite codes; cancel one first' using errcode = 'P0001';
  end if;
  loop
    -- Bytes 0-5 and 10-11 of a random UUID are fully random; 256 is a multiple of 32, so no bias.
    b := uuid_send(gen_random_uuid());
    code := '';
    foreach i in array array[0, 1, 2, 3, 4, 5, 10, 11] loop
      code := code || substr(alphabet, get_byte(b, i) % 32 + 1, 1);
    end loop;
    begin
      insert into public.partners (inviter_id, invite_code) values (me, code) returning partners.id into new_id;
      exit;
    exception when unique_violation then
      -- The same code already exists; draw another.
    end;
  end loop;
  return query select p.id, p.invite_code, p.expires_at from public.partners p where p.id = new_id;
end $$;

create or replace function public.redeem_partner_code(p_code text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  c text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  invite public.partners;
begin
  select * into invite from public.partners p
   where p.invite_code = c and p.status = 'pending' and p.invitee_id is null
   for update;
  if not found or invite.expires_at <= now() then
    raise exception 'partners: this code is not valid or has expired; ask for a new one' using errcode = 'P0001';
  end if;
  if invite.inviter_id = me then
    raise exception 'partners: this is your own code; send it to the player you want to link with' using errcode = 'P0001';
  end if;
  perform public.partner_limit_check(me);
  perform public.partner_limit_check(invite.inviter_id);
  begin
    update public.partners set invitee_id = me, status = 'active', linked_at = now() where id = invite.id;
  exception when unique_violation then
    raise exception 'partners: you are already partners with this player, or an invite between you is waiting' using errcode = 'P0001';
  end;
  return invite.id;
end $$;

-- After an accepted buddy session, either player can invite the other straight from Buddy.
create or replace function public.invite_buddy_as_partner(p_player uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  new_id uuid;
begin
  if not exists (select 1 from public.buddy_requests r where r.status = 'accepted'
                 and ((r.from_player_id = me and r.to_player_id = p_player) or (r.from_player_id = p_player and r.to_player_id = me))) then
    raise exception 'partners: you can invite a buddy once a buddy session between you is accepted' using errcode = 'P0001';
  end if;
  perform public.partner_limit_check(me);
  begin
    insert into public.partners (inviter_id, invitee_id) values (me, p_player) returning id into new_id;
  exception when unique_violation then
    raise exception 'partners: you are already partners with this player, or an invite between you is waiting' using errcode = 'P0001';
  end;
  return new_id;
end $$;

create or replace function public.respond_partner_invite(p_id uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  other uuid;
begin
  select p.inviter_id into other from public.partners p
   where p.id = p_id and p.invitee_id = me and p.status = 'pending' and p.expires_at > now() for update;
  if not found then
    raise exception 'partners: this invite is no longer waiting for your answer' using errcode = 'P0001';
  end if;
  if p_accept then
    perform public.partner_limit_check(me);
    perform public.partner_limit_check(other);
  end if;
  update public.partners
     set status = case when p_accept then 'active' else 'declined' end,
         linked_at = case when p_accept then now() end, ended_at = case when p_accept then null else now() end
   where id = p_id;
end $$;

-- The inviter withdraws a code or an invite nobody has answered yet.
create or replace function public.cancel_partner_invite(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  update public.partners set status = 'cancelled', ended_at = now(), ended_by = me
   where id = p_id and inviter_id = me and status = 'pending';
  if not found then
    raise exception 'partners: only an invite you sent that is still waiting can be cancelled' using errcode = 'P0001';
  end if;
end $$;

-- Either player can unlink at any time; every share between them ends at once.
create or replace function public.end_partnership(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  a uuid;
  b uuid;
begin
  update public.partners set status = 'ended', ended_at = now(), ended_by = me
   where id = p_id and me in (inviter_id, invitee_id) and status = 'active'
   returning inviter_id, invitee_id into a, b;
  if not found then
    raise exception 'partners: only a current partner link can be ended' using errcode = 'P0001';
  end if;
  delete from public.report_shares rs
   where (rs.owner_id = a and rs.partner_id = b) or (rs.owner_id = b and rs.partner_id = a);
end $$;

-- Current partners and waiting invites, with the other player's name and level.
drop function if exists public.my_partners();
create function public.my_partners()
returns table (id uuid, status text, direction text, other_id uuid, other_name text, other_level text,
               invite_code text, created_at timestamptz, expires_at timestamptz, linked_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  return query
  select p.id, p.status, case when p.inviter_id = me then 'sent' else 'received' end,
         o.id, o.display_name, public.buddy_level(o.self_level),
         case when p.inviter_id = me then p.invite_code end, p.created_at, p.expires_at, p.linked_at
  from public.partners p
  left join public.profiles o on o.id = case when p.inviter_id = me then p.invitee_id else p.inviter_id end
  where me in (p.inviter_id, p.invitee_id)
    and (p.status = 'active' or (p.status = 'pending' and p.expires_at > now()))
  order by (p.status = 'active') desc, o.display_name, p.created_at desc
  limit 100;
end $$;

-- ── Sharing ──────────────────────────────────────────────────────────────
create or replace function public.share_session(p_session_id uuid, p_partner_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
begin
  if not exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me) then
    raise exception 'partners: you can share only your own sessions' using errcode = '42501';
  end if;
  if not public.partners_linked(me, p_partner_id) then
    raise exception 'partners: you can share only with a linked partner' using errcode = 'P0001';
  end if;
  insert into public.report_shares (session_id, owner_id, partner_id) values (p_session_id, me, p_partner_id)
  on conflict do nothing;
end $$;

create or replace function public.unshare_session(p_session_id uuid, p_partner_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.report_shares where session_id = p_session_id and partner_id = p_partner_id and owner_id = auth.uid();
end $$;

-- Sessions partners shared with the caller.
drop function if exists public.shared_with_me();
create function public.shared_with_me()
returns table (session_id uuid, owner_id uuid, owner_name text, title text, session_date date,
               session_context text, play_format text, has_report boolean, my_notes bigint, shared_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  return query
  select s.id, s.owner_id, o.display_name, s.title, s.session_date, s.session_context, s.play_format,
         exists (select 1 from public.analysis_results r where r.session_id = s.id),
         (select count(*) from public.peer_notes n where n.session_id = s.id and n.author_id = me),
         rs.created_at
  from public.report_shares rs
  join public.sessions s on s.id = rs.session_id
  join public.profiles o on o.id = rs.owner_id
  where rs.partner_id = me and public.partners_linked(rs.owner_id, me)
  order by s.session_date desc, rs.created_at desc
  limit 200;
end $$;

-- What a partner sees of a shared session: its name, date and format, the
-- video report and the video's storage path. Nothing else from the session.
create or replace function public.shared_report(p_session_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  out jsonb;
begin
  if not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'session', jsonb_build_object('id', s.id, 'title', s.title, 'session_date', s.session_date,
      'session_context', s.session_context, 'play_format', s.play_format, 'owner_id', s.owner_id, 'owner_name', o.display_name),
    'result', (select r.result from public.video_assets v
                 join public.analysis_jobs j on j.video_asset_id = v.id
                 join public.analysis_results r on r.job_id = j.id
                where v.session_id = s.id limit 1),
    'video_path', (select v.storage_path from public.video_assets v
                    where v.session_id = s.id and v.upload_status = 'uploaded'
                      and v.raw_video_deleted_at is null and v.raw_video_deleting_at is null))
  into out
  from public.sessions s join public.profiles o on o.id = s.owner_id
  where s.id = p_session_id;
  return out;
end $$;

-- ── Notes ────────────────────────────────────────────────────────────────
-- Owners see every note on their session; partners see their own.
drop function if exists public.session_peer_notes(uuid);
create function public.session_peer_notes(p_session_id uuid)
returns table (id uuid, author_id uuid, author_name text, mine boolean, video_time_s numeric,
               body text, created_at timestamptz, updated_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  is_owner boolean;
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  is_owner := exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me);
  if not is_owner and not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  return query
  select n.id, n.author_id, a.display_name, n.author_id = me, n.video_time_s, n.body, n.created_at, n.updated_at
  from public.peer_notes n join public.profiles a on a.id = n.author_id
  where n.session_id = p_session_id and (is_owner or n.author_id = me)
  order by n.video_time_s nulls first, n.created_at
  limit 500;
end $$;

create or replace function public.add_peer_note(p_session_id uuid, p_video_time_s numeric, p_body text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  text_ text := btrim(coalesce(p_body, ''), E' \t\r\n');
  new_id uuid;
begin
  if not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  if char_length(text_) not between 1 and 500 then
    raise exception 'partners: write a note of 1 to 500 characters' using errcode = '22023';
  end if;
  if p_video_time_s is not null and p_video_time_s not between 0 and 36000 then
    raise exception 'partners: the video time is not valid' using errcode = '22023';
  end if;
  if (select count(*) from public.peer_notes n where n.session_id = p_session_id and n.author_id = me) >= 200 then
    raise exception 'partners: you can leave at most 200 notes on one session' using errcode = 'P0001';
  end if;
  insert into public.peer_notes (session_id, owner_id, author_id, video_time_s, body)
  select s.id, s.owner_id, me, round(p_video_time_s, 2), text_ from public.sessions s where s.id = p_session_id
  returning id into new_id;
  return new_id;
end $$;

-- Authors edit only their own notes, and only while the session is shared with them.
create or replace function public.edit_peer_note(p_id uuid, p_body text) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  text_ text := btrim(coalesce(p_body, ''), E' \t\r\n');
begin
  if char_length(text_) not between 1 and 500 then
    raise exception 'partners: write a note of 1 to 500 characters' using errcode = '22023';
  end if;
  update public.peer_notes n set body = text_, updated_at = now()
   where n.id = p_id and n.author_id = me and public.partner_can_view(n.session_id);
  if not found then
    raise exception 'partners: you can edit only your own notes on a session shared with you' using errcode = '42501';
  end if;
end $$;

-- The author (while shared) or the session owner (always) can delete a note.
create or replace function public.delete_peer_note(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  delete from public.peer_notes n
   where n.id = p_id and (n.owner_id = me or (n.author_id = me and public.partner_can_view(n.session_id)));
  if not found then
    raise exception 'partners: you can delete only your own notes or notes on your sessions' using errcode = '42501';
  end if;
end $$;

revoke all on function public.partner_check_caller(), public.partners_linked(uuid, uuid), public.partner_can_view(uuid),
  public.partner_can_view_video(text), public.partner_limit_check(uuid), public.create_partner_invite(),
  public.redeem_partner_code(text), public.invite_buddy_as_partner(uuid), public.respond_partner_invite(uuid, boolean),
  public.cancel_partner_invite(uuid), public.end_partnership(uuid), public.my_partners(),
  public.share_session(uuid, uuid), public.unshare_session(uuid, uuid), public.shared_with_me(), public.shared_report(uuid),
  public.session_peer_notes(uuid), public.add_peer_note(uuid, numeric, text), public.edit_peer_note(uuid, text),
  public.delete_peer_note(uuid) from public, anon;
-- partner_can_view and partner_can_view_video are used inside row and storage policies.
grant execute on function public.partner_can_view(uuid), public.partner_can_view_video(text), public.create_partner_invite(),
  public.redeem_partner_code(text), public.invite_buddy_as_partner(uuid), public.respond_partner_invite(uuid, boolean),
  public.cancel_partner_invite(uuid), public.end_partnership(uuid), public.my_partners(),
  public.share_session(uuid, uuid), public.unshare_session(uuid, uuid), public.shared_with_me(), public.shared_report(uuid),
  public.session_peer_notes(uuid), public.add_peer_note(uuid, numeric, text), public.edit_peer_note(uuid, text),
  public.delete_peer_note(uuid) to authenticated;


-- ════════════════ 20261105090000_baseline_tests.sql ════════════════

-- Measured court tests (adviser feedback #5, work package WP4): a player
-- records simple counted drills, such as deep serves out of 20, as an
-- objective baseline next to their self-ratings, and re-tests later. Every
-- save adds rows, so the history is kept.
-- Run AFTER 20261024090000_partners.sql. Safe to run more than once.

create table if not exists public.baseline_tests (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- Keys and limits must match src/lib/coaching/baselineTests.ts (checked by its tests).
  test_key text not null check (test_key in ('deep_serves', 'dinks_in_a_row', 'third_shot_drops', 'deep_returns', 'rally_to_20')),
  value smallint not null check (value between 0 and 500),
  -- How many tries the count is out of; empty for "best run" tests.
  out_of smallint,
  tested_on date not null default current_date,
  created_at timestamptz not null default now(),
  constraint baseline_tests_out_of check (case test_key
    when 'deep_serves' then out_of = 20
    when 'third_shot_drops' then out_of = 10
    when 'deep_returns' then out_of = 10
    when 'rally_to_20' then out_of = 20
    when 'dinks_in_a_row' then out_of is null
  end),
  constraint baseline_tests_value_in_range check (out_of is null or value <= out_of),
  -- One day of slack for players in time zones ahead of the server.
  constraint baseline_tests_date check (tested_on between date '2020-01-01' and current_date + 1)
);
create index if not exists baseline_tests_owner_date on public.baseline_tests (owner_id, tested_on, created_at);

-- Private to the player: nobody else, partners included, can read or change them.
alter table public.baseline_tests enable row level security;
drop policy if exists baseline_tests_owner on public.baseline_tests;
create policy baseline_tests_owner on public.baseline_tests for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
revoke all on public.baseline_tests from anon, authenticated;
grant select, insert, update, delete on public.baseline_tests to authenticated;
grant all on public.baseline_tests to service_role;


-- ════════════════ 20261105100000_peer_feedback.sql ════════════════

-- Targeted peer feedback (adviser feedback #4a/#4b, work package WP5).
-- When sharing a session, the owner picks up to 3 skills to get feedback on,
-- and whether the partner sees the video ("with video") or only rates
-- ("ratings only", also for sessions without a video). The partner rates only
-- those skills on the same 1-5 scale and can tag notes with one of them.
-- Everything else stays private (M02): a partner never sees the owner's own
-- ratings, journal, plan or goals.
-- Run AFTER 20261105090000_baseline_tests.sql. Safe to run more than once; if
-- 20261024090000_partners.sql is run again later, run this file again too.

-- The 10 skill keys, as in public.valid_self_ratings and src/lib/coaching/selfAssessment.ts.
create or replace function public.self_skill_keys() returns text[]
language sql immutable set search_path = '' as $$
  select array['serve', 'return', 'third_shot', 'dinking', 'volleys',
               'kitchen_line', 'transition', 'footwork', 'consistency', 'strategy']
$$;

-- ── What a share asks for ────────────────────────────────────────────────
alter table public.report_shares
  add column if not exists focus_skills text[] not null default '{}',
  add column if not exists with_video boolean not null default true;
alter table public.report_shares drop constraint if exists report_shares_focus_skills;
alter table public.report_shares add constraint report_shares_focus_skills
  check (cardinality(focus_skills) <= 3 and focus_skills <@ public.self_skill_keys());

-- ── Peer ratings ─────────────────────────────────────────────────────────
create table if not exists public.peer_ratings (
  session_id uuid not null references public.sessions (id) on delete cascade,
  owner_id uuid not null references public.profiles (id) on delete cascade,
  author_id uuid not null references public.profiles (id) on delete cascade,
  skill text not null check (skill = any (public.self_skill_keys())),
  rating smallint not null check (rating between 1 and 5),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (session_id, author_id, skill),
  constraint peer_ratings_not_self check (owner_id <> author_id)
);
create index if not exists peer_ratings_owner on public.peer_ratings (owner_id, updated_at);

-- Notes can be tagged with one of the skills the owner asked about.
alter table public.peer_notes add column if not exists skill text;
alter table public.peer_notes drop constraint if exists peer_notes_skill;
alter table public.peer_notes add constraint peer_notes_skill check (skill is null or skill = any (public.self_skill_keys()));

-- ── Checks ───────────────────────────────────────────────────────────────
-- The caller is a linked partner whose live share of this session asks about this skill.
create or replace function public.partner_can_rate(p_session_id uuid, p_skill text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.report_shares rs
    where rs.session_id = p_session_id and rs.partner_id = auth.uid() and p_skill = any (rs.focus_skills)
      and public.partners_linked(rs.owner_id, rs.partner_id))
$$;

-- Videos are readable only through a share that includes the video.
create or replace function public.partner_can_view_video(p_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.video_assets v
    join public.report_shares rs on rs.session_id = v.session_id
    where v.storage_path = p_name and v.upload_status = 'uploaded' and v.raw_video_deleted_at is null
      and rs.partner_id = auth.uid() and rs.with_video and public.partners_linked(rs.owner_id, rs.partner_id))
$$;

alter table public.peer_ratings enable row level security;
-- Owners read every rating of their sessions; partners read their own, only
-- for skills the owner still asks about, and only while the share lasts.
drop policy if exists peer_ratings_read on public.peer_ratings;
create policy peer_ratings_read on public.peer_ratings for select to authenticated
  using (owner_id = (select auth.uid())
    or (author_id = (select auth.uid()) and public.partner_can_rate(session_id, skill)));
revoke all on public.peer_ratings from anon, authenticated;
grant select on public.peer_ratings to authenticated;
grant all on public.peer_ratings to service_role;

-- ── Sharing with focus skills ────────────────────────────────────────────
drop function if exists public.share_session(uuid, uuid);
create or replace function public.share_session(p_session_id uuid, p_partner_id uuid,
                                                p_focus_skills text[] default '{}', p_with_video boolean default true)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  -- Duplicates removed, the owner's order kept.
  skills text[] := array(select u.s from unnest(coalesce(p_focus_skills, '{}')) with ordinality u(s, i)
                         group by u.s order by min(u.i));
begin
  if not exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me) then
    raise exception 'partners: you can share only your own sessions' using errcode = '42501';
  end if;
  if not public.partners_linked(me, p_partner_id) then
    raise exception 'partners: you can share only with a linked partner' using errcode = 'P0001';
  end if;
  if cardinality(skills) > 3 or not skills <@ public.self_skill_keys() then
    raise exception 'partners: pick up to 3 skills to get feedback on' using errcode = '22023';
  end if;
  insert into public.report_shares (session_id, owner_id, partner_id, focus_skills, with_video)
  values (p_session_id, me, p_partner_id, skills, coalesce(p_with_video, true))
  on conflict (session_id, partner_id) do update set focus_skills = excluded.focus_skills, with_video = excluded.with_video;
end $$;

-- Sessions partners shared with the caller, with what they asked about.
drop function if exists public.shared_with_me();
create function public.shared_with_me()
returns table (session_id uuid, owner_id uuid, owner_name text, title text, session_date date,
               session_context text, play_format text, has_report boolean, my_notes bigint, shared_at timestamptz,
               focus_skills text[], with_video boolean, my_ratings bigint)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  return query
  select s.id, s.owner_id, o.display_name, s.title, s.session_date, s.session_context, s.play_format,
         rs.with_video and exists (select 1 from public.analysis_results r where r.session_id = s.id),
         (select count(*) from public.peer_notes n where n.session_id = s.id and n.author_id = me),
         rs.created_at, rs.focus_skills, rs.with_video,
         (select count(*) from public.peer_ratings pr where pr.session_id = s.id and pr.author_id = me and pr.skill = any (rs.focus_skills))
  from public.report_shares rs
  join public.sessions s on s.id = rs.session_id
  join public.profiles o on o.id = rs.owner_id
  where rs.partner_id = me and public.partners_linked(rs.owner_id, me)
  order by s.session_date desc, rs.created_at desc
  limit 200;
end $$;

-- What a partner sees of a shared session: its name, date and format, the
-- skills the owner asked about, and the video report and video only when the
-- share includes the video. Nothing else from the session.
create or replace function public.shared_report(p_session_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  asked public.report_shares;
  out jsonb;
begin
  select * into asked from public.report_shares rs
   where rs.session_id = p_session_id and rs.partner_id = auth.uid() and public.partners_linked(rs.owner_id, rs.partner_id);
  if not found then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'session', jsonb_build_object('id', s.id, 'title', s.title, 'session_date', s.session_date,
      'session_context', s.session_context, 'play_format', s.play_format, 'owner_id', s.owner_id, 'owner_name', o.display_name),
    'focus_skills', to_jsonb(asked.focus_skills),
    'with_video', asked.with_video,
    'my_ratings', coalesce((select jsonb_object_agg(pr.skill, pr.rating) from public.peer_ratings pr
                             where pr.session_id = s.id and pr.author_id = auth.uid() and pr.skill = any (asked.focus_skills)), '{}'::jsonb),
    'result', case when asked.with_video then (select r.result from public.video_assets v
                 join public.analysis_jobs j on j.video_asset_id = v.id
                 join public.analysis_results r on r.job_id = j.id
                where v.session_id = s.id limit 1) end,
    'video_path', case when asked.with_video then (select v.storage_path from public.video_assets v
                    where v.session_id = s.id and v.upload_status = 'uploaded'
                      and v.raw_video_deleted_at is null and v.raw_video_deleting_at is null) end)
  into out
  from public.sessions s join public.profiles o on o.id = s.owner_id
  where s.id = p_session_id;
  return out;
end $$;

-- ── Rating ───────────────────────────────────────────────────────────────
-- A partner rates one of the skills they were asked about; a null rating removes it.
create or replace function public.rate_shared_skill(p_session_id uuid, p_skill text, p_rating smallint) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
begin
  if not public.partner_can_rate(p_session_id, p_skill) then
    raise exception 'partners: you can rate only the skills you were asked about, on a session shared with you' using errcode = '42501';
  end if;
  if p_rating is null then
    delete from public.peer_ratings where session_id = p_session_id and author_id = me and skill = p_skill;
    return;
  end if;
  if p_rating not between 1 and 5 then
    raise exception 'partners: ratings go from 1 to 5' using errcode = '22023';
  end if;
  insert into public.peer_ratings (session_id, owner_id, author_id, skill, rating)
  select s.id, s.owner_id, me, p_skill, p_rating from public.sessions s where s.id = p_session_id
  on conflict (session_id, author_id, skill) do update set rating = excluded.rating, updated_at = now();
end $$;

-- Owners see every partner's ratings of their session; partners see their own.
drop function if exists public.session_peer_ratings(uuid);
create function public.session_peer_ratings(p_session_id uuid)
returns table (author_id uuid, author_name text, mine boolean, skill text, rating smallint, updated_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  is_owner boolean;
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  is_owner := exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me);
  if not is_owner and not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  return query
  select pr.author_id, a.display_name, pr.author_id = me, pr.skill, pr.rating, pr.updated_at
  from public.peer_ratings pr join public.profiles a on a.id = pr.author_id
  where pr.session_id = p_session_id and (is_owner or (pr.author_id = me and public.partner_can_rate(p_session_id, pr.skill)))
  order by a.display_name, array_position(public.self_skill_keys(), pr.skill);
end $$;

-- ── Notes with a skill tag ───────────────────────────────────────────────
drop function if exists public.session_peer_notes(uuid);
create function public.session_peer_notes(p_session_id uuid)
returns table (id uuid, author_id uuid, author_name text, mine boolean, video_time_s numeric,
               body text, created_at timestamptz, updated_at timestamptz, skill text)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  is_owner boolean;
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  is_owner := exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me);
  if not is_owner and not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  return query
  select n.id, n.author_id, a.display_name, n.author_id = me, n.video_time_s, n.body, n.created_at, n.updated_at, n.skill
  from public.peer_notes n join public.profiles a on a.id = n.author_id
  where n.session_id = p_session_id and (is_owner or n.author_id = me)
  order by n.video_time_s nulls first, n.created_at
  limit 500;
end $$;

-- The skill tag must be one the owner asked about.
create or replace function public.peer_note_skill_ok(p_session_id uuid, p_skill text) returns boolean
language sql stable security definer set search_path = '' as $$
  select p_skill is null or public.partner_can_rate(p_session_id, p_skill)
$$;

drop function if exists public.add_peer_note(uuid, numeric, text);
create or replace function public.add_peer_note(p_session_id uuid, p_video_time_s numeric, p_body text, p_skill text default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  text_ text := btrim(coalesce(p_body, ''), E' \t\r\n');
  new_id uuid;
begin
  if not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  if char_length(text_) not between 1 and 500 then
    raise exception 'partners: write a note of 1 to 500 characters' using errcode = '22023';
  end if;
  if p_video_time_s is not null and p_video_time_s not between 0 and 36000 then
    raise exception 'partners: the video time is not valid' using errcode = '22023';
  end if;
  if not public.peer_note_skill_ok(p_session_id, p_skill) then
    raise exception 'partners: tag a note only with a skill you were asked about' using errcode = '22023';
  end if;
  if (select count(*) from public.peer_notes n where n.session_id = p_session_id and n.author_id = me) >= 200 then
    raise exception 'partners: you can leave at most 200 notes on one session' using errcode = 'P0001';
  end if;
  insert into public.peer_notes (session_id, owner_id, author_id, video_time_s, body, skill)
  select s.id, s.owner_id, me, round(p_video_time_s, 2), text_, p_skill from public.sessions s where s.id = p_session_id
  returning id into new_id;
  return new_id;
end $$;

drop function if exists public.edit_peer_note(uuid, text);
create or replace function public.edit_peer_note(p_id uuid, p_body text, p_skill text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  text_ text := btrim(coalesce(p_body, ''), E' \t\r\n');
  note_session uuid;
begin
  if char_length(text_) not between 1 and 500 then
    raise exception 'partners: write a note of 1 to 500 characters' using errcode = '22023';
  end if;
  select n.session_id into note_session from public.peer_notes n
   where n.id = p_id and n.author_id = me and public.partner_can_view(n.session_id);
  if not found then
    raise exception 'partners: you can edit only your own notes on a session shared with you' using errcode = '42501';
  end if;
  if not public.peer_note_skill_ok(note_session, p_skill) then
    raise exception 'partners: tag a note only with a skill you were asked about' using errcode = '22023';
  end if;
  update public.peer_notes set body = text_, skill = p_skill, updated_at = now() where id = p_id;
end $$;

revoke all on function public.self_skill_keys(), public.partner_can_rate(uuid, text), public.partner_can_view_video(text),
  public.share_session(uuid, uuid, text[], boolean), public.shared_with_me(), public.shared_report(uuid),
  public.rate_shared_skill(uuid, text, smallint), public.session_peer_ratings(uuid), public.session_peer_notes(uuid),
  public.peer_note_skill_ok(uuid, text), public.add_peer_note(uuid, numeric, text, text), public.edit_peer_note(uuid, text, text)
  from public, anon;
-- self_skill_keys, partner_can_rate and partner_can_view_video are used inside checks and policies.
grant execute on function public.self_skill_keys(), public.partner_can_rate(uuid, text), public.partner_can_view_video(text),
  public.share_session(uuid, uuid, text[], boolean), public.shared_with_me(), public.shared_report(uuid),
  public.rate_shared_skill(uuid, text, smallint), public.session_peer_ratings(uuid), public.session_peer_notes(uuid),
  public.add_peer_note(uuid, numeric, text, text), public.edit_peer_note(uuid, text, text) to authenticated;


-- ════════════════ 20261105110000_buddy_match.sql ════════════════

-- Buddy matching on performance (adviser feedback #2, work package WP6).
-- Players say what they are looking for (practice, casual games, competition
-- prep). Listed players also show a coarse game rating (their average
-- self-rating over their last 5 rated games, rounded to 0.5) and up to 2
-- strong skills (rated 4+ on average), so Buddy can suggest players at a
-- similar level. Never individual ratings. A logged session can point to the
-- buddy session it came from, so Progress can count games with buddies.
-- Run AFTER 20261105100000_peer_feedback.sql. Safe to run more than once.
-- buddy_players() is left unchanged so the earlier Buddy updates can still be
-- run again; the new details come from buddy_player_details().

alter table public.profiles add column if not exists buddy_looking_for text[] not null default '{}';
alter table public.profiles drop constraint if exists profiles_buddy_looking_for;
alter table public.profiles add constraint profiles_buddy_looking_for
  check (buddy_looking_for <@ array['practice', 'casual_game', 'competition']::text[]);

-- ── Coarse game summary ──────────────────────────────────────────────────
-- Games are court sessions (singles or doubles), as in sessionKind() in the app.
create or replace function public.buddy_game_summary(p_player uuid)
returns table (game_rating numeric, strong_skills text[])
language sql stable security definer set search_path = '' as $$
  with recent as (
    select a.ratings
    from public.self_assessments a join public.sessions s on s.id = a.session_id
    where a.owner_id = p_player and s.play_format in ('singles', 'doubles') and a.ratings <> '{}'::jsonb
    order by s.session_date desc, s.created_at desc
    limit 5
  ), per_game as (
    select (select avg(e.value::numeric) from jsonb_each(r.ratings) e) as rating from recent r
  ), per_skill as (
    select e.key as skill, avg(e.value::numeric) as rating from recent r, jsonb_each(r.ratings) e group by e.key
  )
  select (select round(avg(g.rating) * 2) / 2 from per_game g),
         coalesce((select array_agg(t.skill order by t.rating desc, t.ord) from (
                     select ps.skill, ps.rating, array_position(public.self_skill_keys(), ps.skill) as ord
                     from per_skill ps where ps.rating >= 4
                     order by ps.rating desc, array_position(public.self_skill_keys(), ps.skill) limit 2) t), '{}')
$$;
-- Internal: only the functions below may call it.
revoke all on function public.buddy_game_summary(uuid) from public, anon, authenticated;

-- What a listed player is looking for, with their coarse rating and strong
-- skills. Same players as buddy_players(): opted in, adult, not a guest, not you.
create or replace function public.buddy_player_details()
returns table (player_id uuid, looking_for text[], game_rating numeric, strong_skills text[])
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  return query
  select p.id, p.buddy_looking_for, g.game_rating, g.strong_skills
  from public.profiles p
  join auth.users u on u.id = p.id
  cross join lateral public.buddy_game_summary(p.id) g
  where p.buddy_visible and p.is_adult_confirmed and not coalesce(u.is_anonymous, false) and p.id <> me
  limit 200;
end $$;

-- The caller's own listing, as others see it.
create or replace function public.my_buddy_listing()
returns table (looking_for text[], game_rating numeric, strong_skills text[])
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  return query
  select p.buddy_looking_for, g.game_rating, g.strong_skills
  from public.profiles p cross join lateral public.buddy_game_summary(p.id) g
  where p.id = me;
end $$;

revoke all on function public.buddy_player_details(), public.my_buddy_listing() from public, anon;
grant execute on function public.buddy_player_details(), public.my_buddy_listing() to authenticated;

-- ── Sessions logged from a buddy session ────────────────────────────────
alter table public.sessions add column if not exists buddy_request_id uuid references public.buddy_requests (id) on delete set null;

-- A session may point only to an accepted (or later called-off) buddy session of its owner.
create or replace function public.check_session_buddy_request() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.buddy_request_id is not null
     and (tg_op = 'INSERT' or new.buddy_request_id is distinct from old.buddy_request_id)
     and not exists (select 1 from public.buddy_requests r
                     where r.id = new.buddy_request_id and new.owner_id in (r.from_player_id, r.to_player_id)
                       and r.status in ('accepted', 'called_off')) then
    raise exception 'buddy: a session can be linked only to your own accepted buddy session' using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.check_session_buddy_request() from public, anon, authenticated;
drop trigger if exists sessions_buddy_request_check on public.sessions;
create trigger sessions_buddy_request_check before insert or update of buddy_request_id on public.sessions
  for each row execute function public.check_session_buddy_request();


-- ════════════════ 20261105120000_injury.sql ════════════════

-- "I'm injured" (adviser note: what if the user is injured?). A player can
-- mark that they are injured, for example in the post-game step. While an
-- injury is open the app shows a rest plan, pauses goal deadlines and hides
-- the player from Buddy. "I'm back" closes it and lists them on Buddy again
-- if they were listed before. Not medical advice: the app never asks for a
-- diagnosis, only an optional body area and a short private note.
-- Run AFTER 20261105110000_buddy_match.sql. Safe to run more than once.

create table if not exists public.injury_periods (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- Keys must match INJURY_AREAS in src/lib/coaching/injury.ts (checked by its tests).
  body_area text check (body_area in ('shoulder', 'elbow', 'wrist', 'back', 'hip', 'knee', 'ankle', 'foot', 'other')),
  note text check (char_length(note) <= 500),
  started_on date not null default current_date,
  ended_on date,
  -- Whether the player was listed on Buddy when the injury started, so "I'm back" can list them again.
  was_buddy_visible boolean not null default false,
  created_at timestamptz not null default now(),
  constraint injury_periods_dates check (ended_on is null or ended_on >= started_on)
);
-- At most one open injury per player.
create unique index if not exists injury_periods_one_open on public.injury_periods (owner_id) where ended_on is null;

-- Private to the player: nobody else, partners and coaches included, can read them.
-- Players read and delete their own rows; starting and ending go through the functions below,
-- so the Buddy listing always changes together with the injury.
alter table public.injury_periods enable row level security;
drop policy if exists injury_periods_owner_read on public.injury_periods;
create policy injury_periods_owner_read on public.injury_periods for select to authenticated
  using (owner_id = (select auth.uid()));
drop policy if exists injury_periods_owner_delete on public.injury_periods;
create policy injury_periods_owner_delete on public.injury_periods for delete to authenticated
  using (owner_id = (select auth.uid()));
revoke all on public.injury_periods from anon, authenticated;
grant select, delete on public.injury_periods to authenticated;
grant all on public.injury_periods to service_role;

-- Start an injury, or update the area and note of the open one. Hides the player from Buddy.
create or replace function public.start_injury(p_body_area text default null, p_note text default null)
returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  open_id uuid;
  listed boolean;
begin
  if me is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select id into open_id from public.injury_periods where owner_id = me and ended_on is null;
  if open_id is not null then
    update public.injury_periods set body_area = p_body_area, note = nullif(btrim(p_note), '') where id = open_id;
    return open_id;
  end if;
  select coalesce(buddy_visible, false) into listed from public.profiles where id = me;
  insert into public.injury_periods (owner_id, body_area, note, was_buddy_visible)
  values (me, p_body_area, nullif(btrim(p_note), ''), coalesce(listed, false))
  returning id into open_id;
  update public.profiles set buddy_visible = false where id = me and buddy_visible;
  return open_id;
end $$;

-- "I'm back": close the open injury and list the player on Buddy again if they were listed before.
create or replace function public.end_injury()
returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  relist boolean;
begin
  if me is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  update public.injury_periods set ended_on = greatest(current_date, started_on)
  where owner_id = me and ended_on is null
  returning was_buddy_visible into relist;
  if coalesce(relist, false) then
    update public.profiles set buddy_visible = true where id = me;
  end if;
end $$;

revoke all on function public.start_injury(text, text), public.end_injury() from public, anon;
grant execute on function public.start_injury(text, text), public.end_injury() to authenticated;


-- ════════════════ 20261105130000_buddy_friends.sql ════════════════

-- Buddies as a friend list (team request, 5 Nov 2026). Find a player under
-- Players -> Find and add them as a buddy; they accept or decline. Only then can
-- either of you ask the other to play (a buddy session with purpose, format,
-- place and free times) or partner for video feedback.
--
-- * New table buddies: one row per pair, pending -> active (or declined,
--   cancelled, ended). Rows change only through the functions below.
-- * Players who already had an accepted (or later called-off) buddy session,
--   or are partners, become buddies automatically.
-- * Asking to play and partnering require being buddies (checked by triggers,
--   so every path is covered, partner codes included).
-- * Removing a buddy ends a video partnership between you and withdraws
--   requests still waiting; accepted buddy sessions stay until one of you
--   cancels them.
-- Run AFTER 20261105120000_injury.sql. Safe to run more than once.

create table if not exists public.buddies (
  id uuid primary key default gen_random_uuid(),
  requester_id uuid not null references public.profiles (id) on delete cascade,
  addressee_id uuid not null references public.profiles (id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'active', 'declined', 'cancelled', 'ended')),
  created_at timestamptz not null default now(),
  responded_at timestamptz,
  ended_at timestamptz,
  constraint buddies_not_self check (requester_id <> addressee_id)
);
-- One waiting request or friendship per pair, whoever asked.
create unique index if not exists buddies_one_open_pair on public.buddies
  (least(requester_id, addressee_id), greatest(requester_id, addressee_id)) where status in ('pending', 'active');
create index if not exists buddies_addressee_status on public.buddies (addressee_id, status);
create index if not exists buddies_requester_status on public.buddies (requester_id, status);

alter table public.buddies enable row level security;
drop policy if exists buddies_parties_read on public.buddies;
create policy buddies_parties_read on public.buddies for select to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id));
revoke all on public.buddies from anon, authenticated;
grant select on public.buddies to authenticated;
grant all on public.buddies to service_role;

create or replace function public.are_buddies(p_a uuid, p_b uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.buddies b where b.status = 'active'
                 and ((b.requester_id = p_a and b.addressee_id = p_b) or (b.requester_id = p_b and b.addressee_id = p_a)))
$$;
revoke all on function public.are_buddies(uuid, uuid) from public, anon, authenticated;

-- ── Existing pairs become buddies ─────────────────────────────────────────
insert into public.buddies (requester_id, addressee_id, status, created_at, responded_at)
select distinct on (least(x.a, x.b), greatest(x.a, x.b)) x.a, x.b, 'active', x.created_at, coalesce(x.responded_at, x.created_at)
from (
  select r.from_player_id as a, r.to_player_id as b, r.created_at, r.responded_at
  from public.buddy_requests r where r.status in ('accepted', 'called_off')
  union all
  select p.inviter_id, p.invitee_id, p.created_at, p.linked_at
  from public.partners p where p.status = 'active' and p.invitee_id is not null
) x
where not exists (select 1 from public.buddies b where b.status in ('pending', 'active')
                  and least(b.requester_id, b.addressee_id) = least(x.a, x.b)
                  and greatest(b.requester_id, b.addressee_id) = greatest(x.a, x.b))
order by least(x.a, x.b), greatest(x.a, x.b), x.created_at
on conflict do nothing;

-- ── Adding, answering, cancelling and removing ───────────────────────────
-- Add a listed player as a buddy. If they already asked you, this accepts their request.
create or replace function public.add_buddy(p_player uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
  link public.buddies;
  new_id uuid;
begin
  if not exists (
    select 1 from public.profiles p join auth.users u on u.id = p.id
    where p.id = p_player and p.id <> me and p.buddy_visible and p.is_adult_confirmed and not coalesce(u.is_anonymous, false)
  ) then
    raise exception 'buddy: this player is not available in Buddy' using errcode = 'P0001';
  end if;
  select * into link from public.buddies b where b.status in ('pending', 'active')
    and ((b.requester_id = me and b.addressee_id = p_player) or (b.requester_id = p_player and b.addressee_id = me));
  if found then
    if link.status = 'active' then
      raise exception 'buddy: you are already buddies' using errcode = 'P0001';
    elsif link.requester_id = me then
      raise exception 'buddy: you already asked; waiting for their answer' using errcode = 'P0001';
    end if;
    update public.buddies set status = 'active', responded_at = now() where id = link.id;
    return link.id;
  end if;
  if exists (select 1 from public.buddies b where b.requester_id = me and b.addressee_id = p_player
             and b.status = 'declined' and b.responded_at > now() - interval '7 days') then
    raise exception 'buddy: this player declined recently; you can ask again 7 days after their answer' using errcode = 'P0001';
  end if;
  if (select count(*) from public.buddies b where b.requester_id = me and b.status = 'pending') >= 20 then
    raise exception 'buddy: you already have 20 buddy requests waiting for an answer' using errcode = 'P0001';
  end if;
  insert into public.buddies (requester_id, addressee_id) values (me, p_player) returning id into new_id;
  return new_id;
end $$;

create or replace function public.respond_buddy(p_id uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  update public.buddies set status = case when p_accept then 'active' else 'declined' end, responded_at = now()
   where id = p_id and addressee_id = me and status = 'pending';
  if not found then
    raise exception 'buddy: this buddy request is no longer waiting for your answer' using errcode = 'P0001';
  end if;
end $$;

create or replace function public.cancel_buddy_add(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
begin
  update public.buddies set status = 'cancelled', responded_at = now()
   where id = p_id and requester_id = me and status = 'pending';
  if not found then
    raise exception 'buddy: only a buddy request you sent that is still waiting can be cancelled' using errcode = 'P0001';
  end if;
end $$;

-- Stop being buddies. Ends a video partnership between you and withdraws requests still waiting.
create or replace function public.remove_buddy(p_player uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  update public.buddies set status = 'ended', ended_at = now()
   where status = 'active' and ((requester_id = me and addressee_id = p_player) or (requester_id = p_player and addressee_id = me));
  if not found then
    raise exception 'buddy: you are not buddies with this player' using errcode = 'P0001';
  end if;
  update public.partners set status = case when status = 'active' then 'ended' else 'cancelled' end, ended_at = now(), ended_by = me
   where status in ('pending', 'active') and ((inviter_id = me and invitee_id = p_player) or (inviter_id = p_player and invitee_id = me));
  -- Shares between you go with the partnership (as when unlinking).
  delete from public.report_shares where (owner_id = me and partner_id = p_player) or (owner_id = p_player and partner_id = me);
  update public.buddy_requests set status = 'cancelled', responded_at = now()
   where status = 'pending' and ((from_player_id = me and to_player_id = p_player) or (from_player_id = p_player and to_player_id = me));
end $$;

-- The caller's buddies and buddy requests (waiting or active), with the other player's name and level.
create or replace function public.my_buddies()
returns table (id uuid, status text, direction text, other_id uuid, other_name text, other_level text,
               created_at timestamptz, responded_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  return query
  select b.id, b.status, case when b.requester_id = me then 'sent' else 'received' end,
         o.id, o.display_name, public.buddy_level(o.self_level), b.created_at, b.responded_at
  from public.buddies b
  join public.profiles o on o.id = case when b.requester_id = me then b.addressee_id else b.requester_id end
  where me in (b.requester_id, b.addressee_id) and b.status in ('pending', 'active')
  order by b.status, b.created_at desc
  limit 300;
end $$;

revoke all on function public.add_buddy(uuid), public.respond_buddy(uuid, boolean), public.cancel_buddy_add(uuid),
  public.remove_buddy(uuid), public.my_buddies() from public, anon;
grant execute on function public.add_buddy(uuid), public.respond_buddy(uuid, boolean), public.cancel_buddy_add(uuid),
  public.remove_buddy(uuid), public.my_buddies() to authenticated;

-- ── Asking to play needs a buddy ──────────────────────────────────────────
create or replace function public.check_buddy_request_buddies() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not public.are_buddies(new.from_player_id, new.to_player_id) then
    raise exception 'buddy: add this player as a buddy first; once they accept, you can ask them to play' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists buddy_requests_need_buddies on public.buddy_requests;
create trigger buddy_requests_need_buddies before insert on public.buddy_requests
  for each row execute function public.check_buddy_request_buddies();

-- A buddy can be asked to play even while they are hidden from the Buddy list.
create or replace function public.send_buddy_request(p_to uuid, p_purpose text, p_format text, p_slots jsonb,
                                                     p_city text, p_location text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.buddy_check_caller();
  new_id uuid;
begin
  if not exists (
    select 1 from public.profiles p join auth.users u on u.id = p.id
    where p.id = p_to and p.id <> me and p.is_adult_confirmed and not coalesce(u.is_anonymous, false)
  ) or not public.are_buddies(me, p_to) then
    raise exception 'buddy: add this player as a buddy first; once they accept, you can ask them to play' using errcode = 'P0001';
  end if;
  if not public.buddy_slots_valid(p_slots) then
    raise exception 'buddy: add 1 to 10 free times, each with a date in the next 90 days and a start before the end'
      using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_city, ''))) not between 1 and 60 then
    raise exception 'buddy: enter the city (up to 60 characters)' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_location, ''))) not between 1 and 120 then
    raise exception 'buddy: enter where to meet, such as a court name (up to 120 characters)' using errcode = '22023';
  end if;
  if (select count(*) from public.buddy_requests where from_player_id = me and status = 'pending') >= 10 then
    raise exception 'buddy: you already have 10 requests waiting for an answer' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.buddy_requests where from_player_id = me and to_player_id = p_to
             and status = 'declined' and responded_at > now() - interval '7 days') then
    raise exception 'buddy: this player declined recently; you can ask again 7 days after their answer' using errcode = 'P0001';
  end if;
  begin
    insert into public.buddy_requests (from_player_id, to_player_id, purpose, play_format, slots, city, location)
    values (me, p_to, p_purpose, p_format, p_slots, btrim(p_city), btrim(p_location))
    returning id into new_id;
  exception when unique_violation then
    raise exception 'buddy: there is already an open request between you and this player' using errcode = 'P0001';
  end;
  return new_id;
end $$;
revoke all on function public.send_buddy_request(uuid, text, text, jsonb, text, text) from public, anon;
grant execute on function public.send_buddy_request(uuid, text, text, jsonb, text, text) to authenticated;

-- ── Video partners need a buddy ───────────────────────────────────────────
create or replace function public.check_partner_buddies() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.invitee_id is not null and new.status in ('pending', 'active')
     and (tg_op = 'INSERT' or old.invitee_id is distinct from new.invitee_id or old.status is distinct from new.status)
     and not public.are_buddies(new.inviter_id, new.invitee_id) then
    raise exception 'partners: you can partner only with a buddy; add them as a buddy first' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists partners_need_buddies on public.partners;
create trigger partners_need_buddies before insert or update on public.partners
  for each row execute function public.check_partner_buddies();

-- Any buddy can be invited to be a video partner (before: only after an accepted buddy session).
create or replace function public.invite_buddy_as_partner(p_player uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  new_id uuid;
begin
  if not public.are_buddies(me, p_player) then
    raise exception 'partners: you can partner only with a buddy; add them as a buddy first' using errcode = 'P0001';
  end if;
  perform public.partner_limit_check(me);
  begin
    insert into public.partners (inviter_id, invitee_id) values (me, p_player) returning id into new_id;
  exception when unique_violation then
    raise exception 'partners: you are already partners with this player, or an invite between you is waiting' using errcode = 'P0001';
  end;
  return new_id;
end $$;


-- ════════════════ 20261108132612_data_consent.sql ════════════════

-- Additive, separate from recording_upload consent_records.
-- profiles_self already covers SELECT/INSERT/UPDATE with auth.uid() = id.
alter table public.profiles
  add column if not exists data_consent_version text,
  add column if not exists data_consent_at timestamptz,
  add column if not exists analytics_opt_in boolean not null default false,
  add column if not exists research_opt_in boolean not null default false;


-- ════════════════ 20261109090000_buddy_game_shares.sql ════════════════

-- Buddy game shares: when you name a buddy as a player in a game, that game
-- (with its video and analysis, read-only) can appear on the buddy's account.
-- The buddy is asked each time, unless they chose "Accept automatically" or
-- "Always accept from <you>". Additive only: no existing table or policy changes.

-- The tagged player's choice: 'ask' (default) or 'auto'.
alter table public.profiles
  add column if not exists game_share_mode text not null default 'ask';
do $$ begin
  alter table public.profiles add constraint profiles_game_share_mode_check check (game_share_mode in ('ask', 'auto'));
exception when duplicate_object then null; end $$;

create table if not exists public.game_tags (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions(id) on delete cascade,
  owner_id uuid not null references auth.users(id) on delete cascade,
  tagged_id uuid not null references auth.users(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined')),
  created_at timestamptz not null default now(),
  responded_at timestamptz,
  unique (session_id, tagged_id),
  check (owner_id <> tagged_id)
);
create index if not exists game_tags_tagged_idx on public.game_tags (tagged_id, status);

-- "Always accept from this buddy."
create table if not exists public.game_tag_trust (
  player_id uuid not null references auth.users(id) on delete cascade,
  trusted_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (player_id, trusted_id)
);

alter table public.game_tags enable row level security;
alter table public.game_tag_trust enable row level security;
drop policy if exists game_tags_parties_read on public.game_tags;
create policy game_tags_parties_read on public.game_tags for select to authenticated
  using (owner_id = (select auth.uid()) or tagged_id = (select auth.uid()));
drop policy if exists game_tag_trust_own_read on public.game_tag_trust;
create policy game_tag_trust_own_read on public.game_tag_trust for select to authenticated
  using (player_id = (select auth.uid()));
revoke all on public.game_tags, public.game_tag_trust from anon, authenticated;
grant select on public.game_tags, public.game_tag_trust to authenticated;
grant all on public.game_tags, public.game_tag_trust to service_role;

-- The caller accepted this game and is still the owner's buddy.
create or replace function public.game_tag_can_view(p_session_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.game_tags t
    where t.session_id = p_session_id and t.tagged_id = auth.uid() and t.status = 'accepted'
      and public.are_buddies(t.owner_id, t.tagged_id))
$$;

create or replace function public.game_tag_can_view_video(p_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.video_assets v
    where v.storage_path = p_name and v.upload_status = 'uploaded' and v.raw_video_deleted_at is null
      and public.game_tag_can_view(v.session_id))
$$;

-- A tagged buddy may create a short-lived signed link to the game's video.
drop policy if exists session_videos_select_tagged on storage.objects;
create policy session_videos_select_tagged on storage.objects for select to authenticated
  using (bucket_id = 'session-videos' and public.game_tag_can_view_video(name));

-- Owner: share the game with these buddies (others are ignored). Returns how many were asked or added.
create or replace function public.tag_buddies_in_game(p_session_id uuid, p_players uuid[]) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  p uuid;
  n integer := 0;
  auto boolean;
begin
  if me is null then raise exception 'game shares: sign in first' using errcode = '42501'; end if;
  if not exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me) then
    raise exception 'game shares: only the player who logged the game can share it' using errcode = '42501';
  end if;
  foreach p in array coalesce(p_players, '{}'::uuid[]) loop
    continue when p = me or not public.are_buddies(me, p);
    select coalesce(pr.game_share_mode = 'auto', false)
           or exists (select 1 from public.game_tag_trust tr where tr.player_id = p and tr.trusted_id = me)
      into auto from public.profiles pr where pr.id = p;
    insert into public.game_tags (session_id, owner_id, tagged_id, status, responded_at)
    values (p_session_id, me, p, case when coalesce(auto, false) then 'accepted' else 'pending' end,
            case when coalesce(auto, false) then now() end)
    on conflict (session_id, tagged_id) do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;

-- Owner: stop sharing the game with one buddy.
create or replace function public.untag_buddy_in_game(p_session_id uuid, p_player uuid) returns void
language sql security definer set search_path = '' as $$
  delete from public.game_tags t where t.session_id = p_session_id and t.owner_id = auth.uid() and t.tagged_id = p_player
$$;

-- Tagged buddy: accept or decline; "always" also trusts this buddy for future games.
create or replace function public.respond_game_tag(p_id uuid, p_accept boolean, p_always boolean default false) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  t public.game_tags;
begin
  select * into t from public.game_tags where id = p_id and tagged_id = me;
  if not found then raise exception 'game shares: request not found' using errcode = 'P0002'; end if;
  update public.game_tags set status = case when p_accept then 'accepted' else 'declined' end, responded_at = now()
   where id = p_id;
  if p_accept and p_always then
    insert into public.game_tag_trust (player_id, trusted_id) values (me, t.owner_id) on conflict do nothing;
  end if;
end $$;

-- Tagged buddy: remove an accepted game from their Sessions.
create or replace function public.hide_shared_game(p_session_id uuid) returns void
language sql security definer set search_path = '' as $$
  update public.game_tags set status = 'declined', responded_at = now()
   where session_id = p_session_id and tagged_id = auth.uid()
$$;

-- Tagged buddy: start being asked again for everyone.
create or replace function public.clear_game_tag_trust() returns void
language sql security definer set search_path = '' as $$
  delete from public.game_tag_trust where player_id = auth.uid()
$$;

-- Games waiting for the caller's answer, and games they accepted.
create or replace function public.my_game_shares()
returns table (id uuid, session_id uuid, status text, owner_id uuid, owner_name text, title text, session_date date,
               session_context text, play_format text, match_result text, match_score text, has_video boolean, created_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then raise exception 'game shares: sign in first' using errcode = '42501'; end if;
  return query
  select t.id, s.id, t.status, s.owner_id, o.display_name, s.title, s.session_date, s.session_context, s.play_format,
         s.match_result, s.match_score,
         exists (select 1 from public.video_assets v where v.session_id = s.id and v.upload_status = 'uploaded'),
         t.created_at
  from public.game_tags t
  join public.sessions s on s.id = t.session_id
  join public.profiles o on o.id = t.owner_id
  where t.tagged_id = me and t.status in ('pending', 'accepted') and public.are_buddies(t.owner_id, me)
  order by s.session_date desc, t.created_at desc
  limit 200;
end $$;

-- What a tagged buddy sees: the game's name, date, format, score, named players,
-- the video analysis and the video's storage path. Not the owner's ratings or journal.
create or replace function public.shared_game(p_session_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  out jsonb;
begin
  if not public.game_tag_can_view(p_session_id) then
    raise exception 'game shares: this game is not shared with you' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'session', jsonb_build_object('id', s.id, 'title', s.title, 'session_date', s.session_date,
      'session_context', s.session_context, 'play_format', s.play_format, 'match_result', s.match_result,
      'match_score', s.match_score, 'owner_id', s.owner_id, 'owner_name', o.display_name),
    'players', coalesce((select jsonb_agg(jsonb_build_object('role', sp.role, 'display_name', sp.display_name))
                          from public.session_participants sp
                         where sp.session_id = s.id and sp.role in ('partner', 'opponent') and sp.display_name is not null), '[]'::jsonb),
    'result', (select r.result from public.video_assets v
                 join public.analysis_jobs j on j.video_asset_id = v.id
                 join public.analysis_results r on r.job_id = j.id
                where v.session_id = s.id limit 1),
    'video_path', (select v.storage_path from public.video_assets v
                    where v.session_id = s.id and v.upload_status = 'uploaded'
                      and v.raw_video_deleted_at is null and v.raw_video_deleting_at is null))
  into out
  from public.sessions s join public.profiles o on o.id = s.owner_id
  where s.id = p_session_id;
  return out;
end $$;

revoke all on function public.game_tag_can_view(uuid), public.game_tag_can_view_video(text),
  public.tag_buddies_in_game(uuid, uuid[]), public.untag_buddy_in_game(uuid, uuid),
  public.respond_game_tag(uuid, boolean, boolean), public.hide_shared_game(uuid), public.clear_game_tag_trust(),
  public.my_game_shares(), public.shared_game(uuid) from public, anon;
grant execute on function public.tag_buddies_in_game(uuid, uuid[]), public.untag_buddy_in_game(uuid, uuid),
  public.respond_game_tag(uuid, boolean, boolean), public.hide_shared_game(uuid), public.clear_game_tag_trust(),
  public.my_game_shares(), public.shared_game(uuid) to authenticated;
grant execute on function public.game_tag_can_view(uuid), public.game_tag_can_view_video(text) to authenticated;


-- ════════════════ 20261110090000_shot_results_goal_weeks.sql ════════════════

-- Adviser notes of 7 Nov 2026:
-- * Shots are rated as successes out of 10 ("Out of 10 serves, how many went in?")
--   instead of 1-5. The 1-5 rating that follows from the count is still saved in
--   `ratings`, so plans, Progress and peer comparisons work as before; the count
--   itself is kept here so the plan can quote it ("6 of 10 serves in").
-- * The goal length is a setting: any number of weeks from 1 to 52 (default 4).
-- Run AFTER 20261105130000_buddy_friends.sql. Safe to run more than once.

alter table public.self_assessments add column if not exists shot_results jsonb not null default '{}'::jsonb;

-- Keys must match the shots in src/lib/coaching/selfAssessment.ts (checked by its tests); whole numbers 0 to 10.
create or replace function public.valid_shot_results(p jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(p) = 'object' and not exists (
    select 1 from jsonb_each(p) e
    where e.key not in ('serve', 'return', 'third_shot', 'dinking', 'volleys')
       or jsonb_typeof(e.value) <> 'number'
       or (e.value #>> '{}')::numeric not between 0 and 10
       or (e.value #>> '{}')::numeric <> trunc((e.value #>> '{}')::numeric))
$$;
alter table public.self_assessments drop constraint if exists self_assessments_shot_results;
alter table public.self_assessments add constraint self_assessments_shot_results check (public.valid_shot_results(shot_results));

alter table public.profiles add column if not exists goal_weeks smallint not null default 4;
alter table public.profiles drop constraint if exists profiles_goal_weeks;
alter table public.profiles add constraint profiles_goal_weeks check (goal_weeks between 1 and 52);


-- ════════════════ 20261111090000_video_comments_player_photos.sql ════════════════

-- Video comments for everyone on a shared session, and players' profile photos (adviser notes, 10 Nov 2026).
--
-- 1. Comments on a shared video: the owner can now comment too (pinned to a second of the video,
--    like partners), and everyone who can open the session sees every comment on it: the owner and
--    each partner it is shared with. Before, a partner saw only their own notes and the owner could
--    only read and delete them. Each author still edits only their own comments; the owner can
--    delete any comment on their session.
-- 2. Every signed-in player can see every player's profile photo (adviser request: photos on the
--    Players tab). player_photos() gives the photo paths for the players on screen.
-- 3. A cancelled buddy session can be removed from your own list (hidden for you only).
--
-- Safe to run more than once.

-- ── 1. Comments ──────────────────────────────────────────────────────────
create or replace function public.add_peer_note(p_session_id uuid, p_video_time_s numeric, p_body text, p_skill text default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.partner_check_caller();
  text_ text := btrim(coalesce(p_body, ''), E' \t\r\n');
  is_owner boolean;
  new_id uuid;
begin
  is_owner := exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me);
  if not is_owner and not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  if char_length(text_) not between 1 and 500 then
    raise exception 'partners: write a note of 1 to 500 characters' using errcode = '22023';
  end if;
  if p_video_time_s is not null and p_video_time_s not between 0 and 36000 then
    raise exception 'partners: the video time is not valid' using errcode = '22023';
  end if;
  -- Partners tag a comment only with a skill they were asked about; the owner does not tag.
  if (is_owner and p_skill is not null) or (not is_owner and not public.peer_note_skill_ok(p_session_id, p_skill)) then
    raise exception 'partners: tag a note only with a skill you were asked about' using errcode = '22023';
  end if;
  if (select count(*) from public.peer_notes n where n.session_id = p_session_id and n.author_id = me) >= 200 then
    raise exception 'partners: you can leave at most 200 notes on one session' using errcode = 'P0001';
  end if;
  insert into public.peer_notes (session_id, owner_id, author_id, video_time_s, body, skill)
  select s.id, s.owner_id, me, round(p_video_time_s, 2), text_, p_skill from public.sessions s where s.id = p_session_id
  returning id into new_id;
  return new_id;
end $$;

create or replace function public.edit_peer_note(p_id uuid, p_body text, p_skill text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  text_ text := btrim(coalesce(p_body, ''), E' \t\r\n');
  note public.peer_notes;
begin
  if char_length(text_) not between 1 and 500 then
    raise exception 'partners: write a note of 1 to 500 characters' using errcode = '22023';
  end if;
  -- Your own comment, on your own session or on one still shared with you.
  select * into note from public.peer_notes n
   where n.id = p_id and n.author_id = me and (n.owner_id = me or public.partner_can_view(n.session_id));
  if not found then
    raise exception 'partners: you can edit only your own notes on a session shared with you' using errcode = '42501';
  end if;
  if (note.owner_id = me and p_skill is not null) or (note.owner_id <> me and not public.peer_note_skill_ok(note.session_id, p_skill)) then
    raise exception 'partners: tag a note only with a skill you were asked about' using errcode = '22023';
  end if;
  update public.peer_notes set body = text_, skill = p_skill, updated_at = now() where id = p_id;
end $$;

-- Everyone who can open the session reads every comment on it.
create or replace function public.session_peer_notes(p_session_id uuid)
returns table (id uuid, author_id uuid, author_name text, mine boolean, video_time_s numeric,
               body text, created_at timestamptz, updated_at timestamptz, skill text)
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'partners: sign in first' using errcode = '42501';
  end if;
  if not exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me)
     and not public.partner_can_view(p_session_id) then
    raise exception 'partners: this session is not shared with you' using errcode = '42501';
  end if;
  return query
  select n.id, n.author_id, a.display_name, n.author_id = me, n.video_time_s, n.body, n.created_at, n.updated_at, n.skill
  from public.peer_notes n join public.profiles a on a.id = n.author_id
  where n.session_id = p_session_id
  order by n.video_time_s nulls first, n.created_at
  limit 500;
end $$;

revoke all on function public.add_peer_note(uuid, numeric, text, text), public.edit_peer_note(uuid, text, text),
  public.session_peer_notes(uuid) from public, anon;
grant execute on function public.add_peer_note(uuid, numeric, text, text), public.edit_peer_note(uuid, text, text),
  public.session_peer_notes(uuid) to authenticated;

-- ── 2. Players' photos ───────────────────────────────────────────────────
-- Every signed-in player (not guests) can see every player's profile photo, so photos
-- show on the Players tab: Find, requests and partner cards. Uploading, changing and
-- deleting stay limited to the photo's owner.
drop policy if exists profile_photos_select_buddies on storage.objects;
drop policy if exists profile_photos_select_players on storage.objects;
create policy profile_photos_select_players on storage.objects for select to authenticated
  using (bucket_id = 'profile-photos' and not coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false));

-- Photo paths for the players on screen (at most 500 at a time). Only the path: nothing
-- else from the profile.
create or replace function public.player_photos(p_ids uuid[])
returns table (player_id uuid, avatar_path text)
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'players: sign in with an account first' using errcode = '42501';
  end if;
  if coalesce(array_length(p_ids, 1), 0) > 500 then
    raise exception 'players: ask for at most 500 photos at a time' using errcode = '22023';
  end if;
  return query
  select p.id, p.avatar_path from public.profiles p where p.id = any (p_ids) and p.avatar_path is not null;
end $$;
revoke all on function public.player_photos(uuid[]) from public, anon;
grant execute on function public.player_photos(uuid[]) to authenticated;

-- ── 3. Removing cancelled buddy sessions from your list ──────────────────
-- A cancelled ("called off") buddy session can be removed from your own list. It is only
-- hidden for you: the other player still sees it until they remove it too.
create table if not exists public.hidden_buddy_sessions (
  request_id uuid not null references public.buddy_requests (id) on delete cascade,
  player_id uuid not null references public.profiles (id) on delete cascade,
  hidden_at timestamptz not null default now(),
  primary key (request_id, player_id)
);
alter table public.hidden_buddy_sessions enable row level security;
drop policy if exists hidden_buddy_sessions_own_read on public.hidden_buddy_sessions;
create policy hidden_buddy_sessions_own_read on public.hidden_buddy_sessions for select to authenticated
  using (player_id = (select auth.uid()));
revoke all on public.hidden_buddy_sessions from anon, authenticated;
grant select on public.hidden_buddy_sessions to authenticated;
grant all on public.hidden_buddy_sessions to service_role;

create or replace function public.hide_cancelled_session(p_request_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'buddy: sign in first' using errcode = '42501';
  end if;
  if not exists (select 1 from public.buddy_requests r where r.id = p_request_id and r.status = 'called_off'
                 and me in (r.from_player_id, r.to_player_id)) then
    raise exception 'buddy: only your cancelled sessions can be removed' using errcode = '42501';
  end if;
  insert into public.hidden_buddy_sessions (request_id, player_id) values (p_request_id, me) on conflict do nothing;
end $$;
revoke all on function public.hide_cancelled_session(uuid) from public, anon;
grant execute on function public.hide_cancelled_session(uuid) to authenticated;


-- ════════════════ 20261112090000_buddy_session_video.sql ════════════════

-- One video per buddy game (adviser notes, 10 Nov 2026).
--
-- When two buddies played a buddy session and each logged it (sessions.buddy_request_id),
-- only the player who asked to play uploads the video. The other player adds that same
-- video to their own session with one tap: the file is copied into their folder and
-- analysed for them, so they get their own report without uploading.
-- The uploader can turn this off per video ("Let Kirk use this video", on by default).
--
-- * video_assets.copied_from: the video a copy was made from.
-- * video_assets.buddy_can_use: the uploader lets the other player add it (default true).
-- * The other player (the one who was asked) cannot upload to a buddy-session game;
--   they add the asker's video instead.
-- * buddy_session_video(session): who uploads, and whether a video is ready to add.
-- * add_buddy_session_video(session): registers the copy; the app then copies the file
--   in Storage and finalises it like an upload.
-- * set_buddy_can_use(video, allowed): the uploader's switch.
--
-- Safe to run more than once.

alter table public.video_assets add column if not exists copied_from uuid references public.video_assets (id) on delete set null;
alter table public.video_assets add column if not exists buddy_can_use boolean not null default true;

-- The buddy session a game was logged from, and the caller's side of it.
create or replace function public.buddy_game_link(p_session_id uuid)
returns table (request_id uuid, asker uuid, asked uuid, owner_id uuid)
language sql stable security definer set search_path = '' as $$
  select r.id, r.from_player_id, r.to_player_id, s.owner_id
  from public.sessions s join public.buddy_requests r on r.id = s.buddy_request_id
  where s.id = p_session_id and s.owner_id in (r.from_player_id, r.to_player_id)
$$;
revoke all on function public.buddy_game_link(uuid) from public, anon, authenticated;

-- The asker's uploaded video of the same buddy game (the newest, if they logged it twice).
create or replace function public.buddy_game_source_video(p_session_id uuid) returns public.video_assets
language sql stable security definer set search_path = '' as $$
  select v.* from public.buddy_game_link(p_session_id) l
  join public.sessions s2 on s2.buddy_request_id = l.request_id and s2.owner_id = l.asker
  join public.video_assets v on v.session_id = s2.id
  where l.owner_id = l.asked and v.upload_status = 'uploaded' and v.raw_video_deleted_at is null
    and v.raw_video_deleting_at is null and v.copied_from is null
  order by v.uploaded_at desc nulls last
  limit 1
$$;
revoke all on function public.buddy_game_source_video(uuid) from public, anon, authenticated;

-- The player who was asked uploads nothing to a buddy game: they add the asker's video.
create or replace function public.buddy_game_upload_rule() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.copied_from is null and exists (select 1 from public.buddy_game_link(new.session_id) l where l.owner_id = l.asked) then
    raise exception 'buddy_game_video_from_asker' using errcode = '42501',
      hint = 'In a buddy game, the player who asked to play uploads the video; the other player adds it.';
  end if;
  return new;
end $$;
revoke all on function public.buddy_game_upload_rule() from public, anon, authenticated;
drop trigger if exists video_asset_buddy_game_rule on public.video_assets;
create trigger video_asset_buddy_game_rule before insert on public.video_assets
  for each row execute function public.buddy_game_upload_rule();

-- What the session page needs: { role: 'asker' | 'asked' | null, other_name,
--   video: { id, original_filename, byte_size, duration_s } | null, allowed, my_video_allowed }.
create or replace function public.buddy_session_video(p_session_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  l record;
  src public.video_assets;
  mine public.video_assets;
begin
  if me is null then raise exception 'buddy: sign in first' using errcode = '42501'; end if;
  if not exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me) then
    raise exception 'buddy: this is not your session' using errcode = '42501';
  end if;
  select * into l from public.buddy_game_link(p_session_id);
  if not found then return jsonb_build_object('role', null); end if;
  select * into mine from public.video_assets v where v.session_id = p_session_id;
  if l.owner_id = l.asker then
    return jsonb_build_object('role', 'asker',
      'other_name', (select p.display_name from public.profiles p where p.id = l.asked),
      'my_video_allowed', mine.buddy_can_use);
  end if;
  src := public.buddy_game_source_video(p_session_id);
  return jsonb_build_object('role', 'asked',
    'other_name', (select p.display_name from public.profiles p where p.id = l.asker),
    'video', case when src.id is null then null else jsonb_build_object('id', src.id, 'original_filename', src.original_filename,
      'byte_size', src.byte_size, 'duration_s', src.duration_s) end,
    'allowed', coalesce(src.buddy_can_use, false));
end $$;

-- Register the copy in the caller's folder. Returns the new video row and the file to copy.
create or replace function public.add_buddy_session_video(p_session_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  src public.video_assets;
  new_id uuid := gen_random_uuid();
  ext text;
  row_ public.video_assets;
begin
  if me is null then raise exception 'buddy: sign in first' using errcode = '42501'; end if;
  if not exists (select 1 from public.sessions s where s.id = p_session_id and s.owner_id = me) then
    raise exception 'buddy: this is not your session' using errcode = '42501';
  end if;
  if not exists (select 1 from public.buddy_game_link(p_session_id) l where l.owner_id = l.asked) then
    raise exception 'buddy: only the player who was asked can add the other player''s video' using errcode = '42501';
  end if;
  if exists (select 1 from public.video_assets v where v.session_id = p_session_id) then
    raise exception 'buddy: this session already has a video' using errcode = '23505';
  end if;
  src := public.buddy_game_source_video(p_session_id);
  if src.id is null then
    raise exception 'buddy: there is no video of this game to add yet' using errcode = 'P0002';
  end if;
  if not src.buddy_can_use then
    raise exception 'buddy: the other player turned off sharing this video' using errcode = '42501';
  end if;
  ext := coalesce(nullif(substring(src.storage_path from '\.([A-Za-z0-9]+)$'), ''), 'mp4');
  insert into public.video_assets (id, owner_id, session_id, storage_path, original_filename, mime_type, byte_size, duration_s, copied_from)
  values (new_id, me, p_session_id, me::text || '/' || p_session_id::text || '/' || new_id::text || '.' || ext,
          src.original_filename, src.mime_type, src.byte_size, src.duration_s, src.id)
  returning * into row_;
  return jsonb_build_object('video', to_jsonb(row_), 'source_path', src.storage_path);
end $$;

-- The uploader's switch: let the other player add this video, or not.
create or replace function public.set_buddy_can_use(p_video_id uuid, p_allowed boolean) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.video_assets set buddy_can_use = coalesce(p_allowed, true)
   where id = p_video_id and owner_id = auth.uid();
  if not found then raise exception 'buddy: video not found' using errcode = 'P0002'; end if;
end $$;

-- The asked player may read (and so copy) the asker's video of their buddy game while it is allowed.
create or replace function public.buddy_can_copy_video(p_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.video_assets v
    join public.sessions s on s.id = v.session_id
    join public.buddy_requests r on r.id = s.buddy_request_id
    where v.storage_path = p_name and v.upload_status = 'uploaded' and v.raw_video_deleted_at is null
      and v.buddy_can_use and v.copied_from is null
      and v.owner_id = r.from_player_id and r.to_player_id = auth.uid()
      and exists (select 1 from public.sessions mine where mine.owner_id = auth.uid() and mine.buddy_request_id = r.id))
$$;
drop policy if exists session_videos_select_buddy_game on storage.objects;
create policy session_videos_select_buddy_game on storage.objects for select to authenticated
  using (bucket_id = 'session-videos' and public.buddy_can_copy_video(name));

revoke all on function public.buddy_session_video(uuid), public.add_buddy_session_video(uuid),
  public.set_buddy_can_use(uuid, boolean), public.buddy_can_copy_video(text) from public, anon;
grant execute on function public.buddy_session_video(uuid), public.add_buddy_session_video(uuid),
  public.set_buddy_can_use(uuid, boolean), public.buddy_can_copy_video(text) to authenticated;


-- ════════════════ 20261113090000_effort_out_of_5.sql ════════════════

-- Every rating in the app is now out of 5. Effort after a game was 1-10: convert saved
-- values to 1-5 (1-2 -> 1, 3-4 -> 2, 5-6 -> 3, 7-8 -> 4, 9-10 -> 5) and allow only 1-5.
-- Runs the conversion only while the old 1-10 rule is still in place, so running it
-- again never halves the values twice.
do $$
declare
  old_rule text;
begin
  select pg_get_constraintdef(c.oid) into old_rule
  from pg_constraint c
  where c.conrelid = 'public.recovery_logs'::regclass and c.conname = 'recovery_logs_exertion_check';
  if old_rule is null or old_rule like '%10%' then
    alter table public.recovery_logs drop constraint if exists recovery_logs_exertion_check;
    update public.recovery_logs set exertion = ceil(exertion / 2.0)::smallint where exertion is not null;
    alter table public.recovery_logs add constraint recovery_logs_exertion_check check (exertion between 1 and 5);
  end if;
end $$;
